('g5_1_math_u5_L02_basic#1','math',5,1,'u5','L02','g5_1_math_u5_L02_basic','lesson_basic','M5-1-u5-C1',1,'mc','auto','⟨1/4⟩ + ⟨1/3⟩을 계산할 때 가장 먼저 할 일은 무엇인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X02']::text[],true,'{"seq":1,"concept":"M5-1-u5-C1","difficulty":1,"kind":"mc","stem":"⟨1/4⟩ + ⟨1/3⟩을 계산할 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"두 분수를 통분한다","correct":true},{"t":"분모끼리 더한다","mis":"M5-1-u5-X01"},{"t":"분자끼리 더한다","mis":"M5-1-u5-X01"},{"t":"분모를 곱한 뒤 분자를 더한다","mis":"M5-1-u5-X02"}],"explanation":["⟨1/4⟩과 ⟨1/3⟩은 분모가 달라 조각의 크기가 달라요.","크기가 다른 조각은 한꺼번에 셀 수 없어요.","그래서 먼저 통분해 조각 크기를 맞춘 뒤 분자끼리 더해요."],"variant_rule":{"alt":[{"stem":"⟨1/2⟩ + ⟨1/5⟩을 계산할 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"두 분수를 통분한다","correct":true},{"t":"분모끼리 더한다","mis":"M5-1-u5-X01"},{"t":"분자끼리 더한다","mis":"M5-1-u5-X01"},{"t":"분모를 곱한 뒤 분자를 더한다","mis":"M5-1-u5-X02"}],"explanation":["⟨1/2⟩과 ⟨1/5⟩은 분모가 달라 조각의 크기가 달라요.","크기가 다른 조각은 한꺼번에 셀 수 없어요.","그래서 먼저 통분해 조각 크기를 맞춘 뒤 분자끼리 더해요."]},{"stem":"⟨1/6⟩ + ⟨1/4⟩을 계산할 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"두 분수를 통분한다","correct":true},{"t":"분모끼리 더한다","mis":"M5-1-u5-X01"},{"t":"분자끼리 더한다","mis":"M5-1-u5-X01"},{"t":"분모를 곱한 뒤 분자를 더한다","mis":"M5-1-u5-X02"}],"explanation":["⟨1/6⟩과 ⟨1/4⟩은 분모가 달라 조각의 크기가 달라요.","크기가 다른 조각은 한꺼번에 셀 수 없어요.","그래서 먼저 통분해 조각 크기를 맞춘 뒤 분자끼리 더해요."]}]}}'::jsonb),
('g5_1_math_u5_L02_basic#2','math',5,1,'u5','L02','g5_1_math_u5_L02_basic','lesson_basic','M5-1-u5-C1',1,'sa','auto','⟨1/4⟩과 ⟨1/3⟩을 통분할 때 공통분모로 알맞은 가장 작은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u5-C1","difficulty":1,"kind":"sa","stem":"⟨1/4⟩과 ⟨1/3⟩을 통분할 때 공통분모로 알맞은 가장 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["공통분모는 두 분모 4와 3의 공배수예요.","가장 작은 공배수는 최소공배수 12예요.","분모의 곱 4 × 3 = 12도 공통분모가 될 수 있지만 가장 작은 수는 12예요."],"variant_rule":{"alt":[{"stem":"⟨1/6⟩과 ⟨1/4⟩을 통분할 때 공통분모로 알맞은 가장 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["공통분모는 두 분모 6과 4의 공배수예요.","가장 작은 공배수는 최소공배수 12예요.","분모의 곱 6 × 4 = 24도 공통분모가 될 수 있지만 가장 작은 수는 12예요."]},{"stem":"⟨1/2⟩과 ⟨1/5⟩을 통분할 때 공통분모로 알맞은 가장 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["공통분모는 두 분모 2와 5의 공배수예요.","가장 작은 공배수는 최소공배수 10이에요.","분모의 곱 2 × 5 = 10도 공통분모가 될 수 있지만 가장 작은 수는 10이에요."]}]}}'::jsonb),
('g5_1_math_u5_L02_basic#3','math',5,1,'u5','L02','g5_1_math_u5_L02_basic','lesson_basic','M5-1-u5-C2',1,'mc','auto','⟨1/2⟩ + ⟨1/5⟩을 계산하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X02']::text[],true,'{"seq":3,"concept":"M5-1-u5-C2","difficulty":1,"kind":"mc","stem":"⟨1/2⟩ + ⟨1/5⟩을 계산하면 얼마인가요?","options":[{"t":"⟨7/10⟩","correct":true},{"t":"⟨2/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨7/20⟩","mis":"M5-1-u5-X03"},{"t":"⟨1/5⟩","mis":"M5-1-u5-X02"}],"explanation":["공통분모 10으로 통분하면 ⟨5/10⟩ + ⟨2/10⟩예요.","분모는 그대로 두고 분자끼리 더하면 ⟨5/10⟩ + ⟨2/10⟩ = ⟨7/10⟩이에요.","그래서 ⟨1/2⟩ + ⟨1/5⟩ = ⟨7/10⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1/3⟩ + ⟨1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨7/12⟩","correct":true},{"t":"⟨2/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨7/24⟩","mis":"M5-1-u5-X03"},{"t":"⟨1/6⟩","mis":"M5-1-u5-X02"}],"explanation":["공통분모 12로 통분하면 ⟨4/12⟩ + ⟨3/12⟩이에요.","분모는 그대로 두고 분자끼리 더하면 ⟨4/12⟩ + ⟨3/12⟩ = ⟨7/12⟩이에요.","그래서 ⟨1/3⟩ + ⟨1/4⟩ = ⟨7/12⟩이에요."]},{"stem":"⟨2/5⟩ + ⟨1/3⟩을 계산하면 얼마인가요?","options":[{"t":"⟨11/15⟩","correct":true},{"t":"⟨3/8⟩","mis":"M5-1-u5-X01"},{"t":"⟨11/30⟩","mis":"M5-1-u5-X03"},{"t":"⟨1/5⟩","mis":"M5-1-u5-X02"}],"explanation":["공통분모 15로 통분하면 ⟨6/15⟩ + ⟨5/15⟩예요.","분모는 그대로 두고 분자끼리 더하면 ⟨6/15⟩ + ⟨5/15⟩ = ⟨11/15⟩이에요.","그래서 ⟨2/5⟩ + ⟨1/3⟩ = ⟨11/15⟩이에요."]}]}}'::jsonb),
('g5_1_math_u5_L02_basic#4','math',5,1,'u5','L02','g5_1_math_u5_L02_basic','lesson_basic','M5-1-u5-C2',1,'sa','auto','⟨2/5⟩ + ⟨1/3⟩을 분모 15로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-1-u5-C2","difficulty":1,"kind":"sa","stem":"⟨2/5⟩ + ⟨1/3⟩을 분모 15로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["분모를 15로 맞추면 ⟨6/15⟩ + ⟨5/15⟩예요.","분모 15는 그대로 두고 분자끼리 6 + 5 = 11이에요.","그래서 분자는 11이에요."],"variant_rule":{"alt":[{"stem":"⟨1/3⟩ + ⟨1/4⟩을 분모 12로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["분모를 12로 맞추면 ⟨4/12⟩ + ⟨3/12⟩이에요.","분모 12는 그대로 두고 분자끼리 4 + 3 = 7이에요.","그래서 분자는 7이에요."]},{"stem":"⟨1/2⟩ + ⟨1/7⟩을 분모 14로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["분모를 14로 맞추면 ⟨7/14⟩ + ⟨2/14⟩예요.","분모 14는 그대로 두고 분자끼리 7 + 2 = 9예요.","그래서 분자는 9예요."]}]}}'::jsonb),
('g5_1_math_u5_L02_basic#5','math',5,1,'u5','L02','g5_1_math_u5_L02_basic','lesson_basic','M5-1-u5-C1',2,'mc','auto','⟨1/4⟩과 ⟨1/3⟩을 그림처럼 12칸으로 맞추어 나타냈어요. 두 분수를 더하면 얼마인가요?',ARRAY['M5-1-u5-X01','M5-1-u5-X03','M5-1-u5-X13']::text[],true,'{"seq":5,"concept":"M5-1-u5-C1","difficulty":2,"kind":"mc","stem":"⟨1/4⟩과 ⟨1/3⟩을 그림처럼 12칸으로 맞추어 나타냈어요. 두 분수를 더하면 얼마인가요?","options":[{"t":"⟨7/12⟩","correct":true},{"t":"⟨2/7⟩","mis":"M5-1-u5-X01"},{"t":"⟨7/24⟩","mis":"M5-1-u5-X03"},{"t":"⟨2/3⟩","mis":"M5-1-u5-X13"}],"explanation":["⟨1/4⟩은 12칸 중 3칸, ⟨1/3⟩은 12칸 중 4칸이에요.","같은 크기의 칸이라 3칸 + 4칸 = 7칸으로 셀 수 있어요.","⟨3/12⟩ + ⟨4/12⟩ = ⟨7/12⟩이에요."],"asset":{"type":"fbar","bars":[{"den":12,"num":3,"label":"⟨1/4⟩"},{"den":12,"num":4,"label":"⟨1/3⟩"}]},"variant_rule":{"alt":[{"stem":"⟨1/2⟩과 ⟨1/6⟩을 그림처럼 6칸으로 맞추어 나타냈어요. 두 분수를 더하면 얼마인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨1/4⟩","mis":"M5-1-u5-X01"},{"t":"⟨1/3⟩","mis":"M5-1-u5-X03"},{"t":"⟨5/6⟩","mis":"M5-1-u5-X13"}],"explanation":["⟨1/2⟩은 6칸 중 3칸, ⟨1/6⟩은 6칸 중 1칸이에요.","같은 크기의 칸이라 3칸 + 1칸 = 4칸으로 셀 수 있어요.","⟨3/6⟩ + ⟨1/6⟩ = ⟨2/3⟩예요."],"asset":{"type":"fbar","bars":[{"den":6,"num":3,"label":"⟨1/2⟩"},{"den":6,"num":1,"label":"⟨1/6⟩"}]}},{"stem":"⟨1/3⟩과 ⟨1/6⟩을 그림처럼 6칸으로 맞추어 나타냈어요. 두 분수를 더하면 얼마인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨2/9⟩","mis":"M5-1-u5-X01"},{"t":"⟨1/4⟩","mis":"M5-1-u5-X03"},{"t":"⟨2/3⟩","mis":"M5-1-u5-X13"}],"explanation":["⟨1/3⟩은 6칸 중 2칸, ⟨1/6⟩은 6칸 중 1칸이에요.","같은 크기의 칸이라 2칸 + 1칸 = 3칸으로 셀 수 있어요.","⟨2/6⟩ + ⟨1/6⟩ = ⟨1/2⟩이에요."],"asset":{"type":"fbar","bars":[{"den":6,"num":2,"label":"⟨1/3⟩"},{"den":6,"num":1,"label":"⟨1/6⟩"}]}}]}}'::jsonb),
('g5_1_math_u5_L02_basic#6','math',5,1,'u5','L02','g5_1_math_u5_L02_basic','lesson_basic','M5-1-u5-C1',2,'ox','auto','⟨1/4⟩ + ⟨1/3⟩의 분모끼리, 분자끼리 더한 ⟨2/7⟩는 바른 답이에요.',ARRAY['M5-1-u5-X01']::text[],true,'{"seq":6,"concept":"M5-1-u5-C1","difficulty":2,"kind":"ox","stem":"⟨1/4⟩ + ⟨1/3⟩의 분모끼리, 분자끼리 더한 ⟨2/7⟩는 바른 답이에요.","answer":"X","reason_options":[{"t":"⟨2/7⟩는 ⟨1/3⟩보다도 작아 더한 값이 될 수 없으므로","correct":true},{"t":"분모끼리, 분자끼리 빠짐없이 더했으므로","mis":"M5-1-u5-X01"}],"mis":"M5-1-u5-X01","explanation":["⟨1/4⟩의 한 칸과 ⟨1/3⟩의 한 칸은 크기가 달라요.","⟨2/7⟩는 ⟨1/3⟩보다 작아요 — 더했는데 작아졌어요.","12로 통분하면 ⟨3/12⟩ + ⟨4/12⟩ = ⟨7/12⟩이 바른 답이에요."],"variant_rule":{"alt":[{"stem":"⟨1/2⟩ + ⟨1/5⟩을 10으로 통분해 계산하면 ⟨7/10⟩이에요.","answer":"O","reason_options":[{"t":"⟨5/10⟩ + ⟨2/10⟩로 조각 크기를 맞춘 뒤 분자끼리 더했으므로","correct":true},{"t":"분모끼리 더하면 7이 되므로","mis":"M5-1-u5-X01"}],"explanation":["⟨1/2⟩ = ⟨5/10⟩, ⟨1/5⟩ = ⟨2/10⟩예요.","분자끼리 5 + 2 = 7이에요.","⟨5/10⟩ + ⟨2/10⟩ = ⟨7/10⟩ — 맞아요."]}]}}'::jsonb),
('g5_1_math_u5_L02_basic#7','math',5,1,'u5','L02','g5_1_math_u5_L02_basic','lesson_basic','M5-1-u5-C2',2,'sa','auto','⟨1/6⟩ + ⟨1/4⟩을 분모 24로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-1-u5-C2","difficulty":2,"kind":"sa","stem":"⟨1/6⟩ + ⟨1/4⟩을 분모 24로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["분모를 24로 맞추면 ⟨4/24⟩ + ⟨6/24⟩이에요.","분모 24는 그대로 두고 분자끼리 4 + 6 = 10이에요.","그래서 분자는 10이에요."],"variant_rule":{"alt":[{"stem":"⟨1/4⟩ + ⟨1/6⟩을 분모 24로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["분모를 24로 맞추면 ⟨6/24⟩ + ⟨4/24⟩예요.","분모 24는 그대로 두고 분자끼리 6 + 4 = 10이에요.","그래서 분자는 10이에요."]},{"stem":"⟨1/6⟩ + ⟨2/9⟩를 분모 54로 통분해 계산했을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["분모를 54로 맞추면 ⟨9/54⟩ + ⟨12/54⟩예요.","분모 54는 그대로 두고 분자끼리 9 + 12 = 21이에요.","그래서 분자는 21이에요."]}]}}'::jsonb),
