('g5_1_math_u5_review_d#18','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C6',3,'sa','auto','⟨7 5/6⟩ − ⟨2 1/2⟩ − ⟨3 1/6⟩을 계산한 값을 ⟨2 □/6⟩로 나타낼 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M5-1-u5-C6","difficulty":3,"kind":"sa","stem":"⟨7 5/6⟩ − ⟨2 1/2⟩ − ⟨3 1/6⟩을 계산한 값을 ⟨2 □/6⟩로 나타낼 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["앞에서부터 셈해요 — ⟨7 5/6⟩ − ⟨2 1/2⟩ = ⟨5 1/3⟩이에요.","⟨5 1/3⟩ − ⟨3 1/6⟩ = ⟨2 1/6⟩이에요.","⟨2 1/6⟩ = ⟨2 1/6⟩ — □는 1이에요."]}'::jsonb),
('g5_1_math_u5_review_d#19','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C7',3,'sa','auto','⟨5 1/5⟩ − ⟨2 1/2⟩을 가분수로 바꾸어 분모 10으로 계산하면 ⟨□/10⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M5-1-u5-C7","difficulty":3,"kind":"sa","stem":"⟨5 1/5⟩ − ⟨2 1/2⟩을 가분수로 바꾸어 분모 10으로 계산하면 ⟨□/10⟩이에요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["⟨5 1/5⟩ = ⟨52/10⟩, ⟨2 1/2⟩ = ⟨25/10⟩예요.","분자끼리 52 − 25 = 27이에요.","⟨27/10⟩ = ⟨2 7/10⟩ — □는 27이에요."]}'::jsonb),
('g5_1_math_u5_review_d#20','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C7',2,'mc','auto','⟨6 1/4⟩ − ⟨3 5/6⟩를 계산하면 얼마인가요?',ARRAY['M5-1-u5-X09','M5-1-u5-X10']::text[],false,'{"seq":20,"concept":"M5-1-u5-C7","difficulty":2,"kind":"mc","stem":"⟨6 1/4⟩ − ⟨3 5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨2 5/12⟩","correct":true},{"t":"⟨3 7/12⟩","mis":"M5-1-u5-X09"},{"t":"⟨3 5/12⟩","mis":"M5-1-u5-X10"},{"t":"⟨2 1/4⟩","mis":"M5-1-u5-X10"}],"explanation":["분수 부분을 12로 통분하면 ⟨6 3/12⟩ − ⟨3 10/12⟩이에요.","분자 3에서 10을 뺄 수 없어 자연수에서 1을 빌리면 ⟨6 3/12⟩ = ⟨5 15/12⟩예요.","⟨5 15/12⟩ − ⟨3 10/12⟩ = ⟨2 5/12⟩예요."]}'::jsonb),
('g5_1_math_u5_review_d#21','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C7',2,'mc','auto','6 − ⟨3 4/9⟩를 계산하면 얼마인가요?',ARRAY['M5-1-u5-X10','M5-1-u5-X09']::text[],false,'{"seq":21,"concept":"M5-1-u5-C7","difficulty":2,"kind":"mc","stem":"6 − ⟨3 4/9⟩를 계산하면 얼마인가요?","options":[{"t":"⟨2 5/9⟩","correct":true},{"t":"⟨3 4/9⟩","mis":"M5-1-u5-X10"},{"t":"⟨2 4/9⟩","mis":"M5-1-u5-X09"},{"t":"⟨3 5/9⟩","mis":"M5-1-u5-X10"}],"explanation":["6에서 1을 빌려 6 = ⟨5 9/9⟩로 바꾸어요 — 1은 ⟨9/9⟩예요.","⟨5 9/9⟩ − ⟨3 4/9⟩ = ⟨2 5/9⟩예요.","그래서 6 − ⟨3 4/9⟩ = ⟨2 5/9⟩예요."]}'::jsonb),
('g5_1_math_u5_review_d#22','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C7',4,'sa','auto','⟨7 1/6⟩에서 분수 부분이 ⟨2/3⟩인 대분수를 뺐더니 ⟨4 1/2⟩이 되었어요. 뺀 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M5-1-u5-C7","difficulty":4,"kind":"sa","stem":"⟨7 1/6⟩에서 분수 부분이 ⟨2/3⟩인 대분수를 뺐더니 ⟨4 1/2⟩이 되었어요. 뺀 대분수의 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["뺀 대분수는 ⟨7 1/6⟩ − ⟨4 1/2⟩로 구해요.","⟨7 1/6⟩ − ⟨4 1/2⟩ = ⟨2 2/3⟩예요 — 분수 부분에서 1을 빌려 와요.","⟨2 2/3⟩의 자연수 부분은 2예요."]}'::jsonb),
('g5_1_math_u5_review_d#23','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C8',4,'sa','auto','집과 도서관 사이는 ⟨1 5/6⟩ km예요. 민서는 집에서, 준우는 도서관에서 서로를 향해 각각 ⟨3/4⟩ km, ⟨2/3⟩ km를 걸었어요. 두 사람 사이에 남은 거리는 ⟨□/12⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M5-1-u5-C8","difficulty":4,"kind":"sa","stem":"집과 도서관 사이는 ⟨1 5/6⟩ km예요. 민서는 집에서, 준우는 도서관에서 서로를 향해 각각 ⟨3/4⟩ km, ⟨2/3⟩ km를 걸었어요. 두 사람 사이에 남은 거리는 ⟨□/12⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["두 사람이 걸은 거리는 ⟨3/4⟩ + ⟨2/3⟩ = ⟨1 5/12⟩ km예요.","남은 거리는 ⟨1 5/6⟩ − ⟨1 5/12⟩ = ⟨22/12⟩ − ⟨17/12⟩ = ⟨5/12⟩ km예요.","그래서 □는 5예요."]}'::jsonb),
('g5_1_math_u5_review_d#24','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C8',2,'mc','auto','학교까지 ⟨1 2/5⟩ km인 길로 왕복하면 모두 몇 km를 걷게 되나요?',ARRAY['M5-1-u5-X11','M5-1-u5-X03','M5-1-u5-X13']::text[],false,'{"seq":24,"concept":"M5-1-u5-C8","difficulty":2,"kind":"mc","stem":"학교까지 ⟨1 2/5⟩ km인 길로 왕복하면 모두 몇 km를 걷게 되나요?","options":[{"t":"⟨2 4/5⟩","correct":true},{"t":"⟨1 2/5⟩","mis":"M5-1-u5-X11"},{"t":"⟨2 2/5⟩","mis":"M5-1-u5-X03"},{"t":"3","mis":"M5-1-u5-X13"}],"explanation":["왕복은 갔다가 돌아오는 것 — 같은 길을 두 번 걸어요.","⟨1 2/5⟩ + ⟨1 2/5⟩ = ⟨2 4/5⟩예요.","그래서 모두 ⟨2 4/5⟩ km예요."]}'::jsonb),
('g5_1_math_u5_review_d#25','math',5,1,'u5','','g5_1_math_u5_review_d','unit_review','M5-1-u5-C8',3,'sa','auto','집에서 학교까지 ⟨1 1/8⟩ km예요. ⟨3/4⟩ km를 걸었다면 남은 거리는 ⟨□/8⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-1-u5-C8","difficulty":3,"kind":"sa","stem":"집에서 학교까지 ⟨1 1/8⟩ km예요. ⟨3/4⟩ km를 걸었다면 남은 거리는 ⟨□/8⟩ km예요. □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["남은 거리 = 전체 거리 − 걸은 거리예요.","⟨1 1/8⟩ − ⟨3/4⟩ = ⟨9/8⟩ − ⟨6/8⟩ = ⟨3/8⟩이에요.","그래서 □는 3이에요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('M5-1-u6-C1','math',5,1,'u6',2,'둘레와 넓이의 뜻 — 둘레는 가장자리를 따라 잰 길이, 넓이는 같은 크기의 칸으로 덮은 칸의 수임을 알고, 둘레가 같아도 넓이는 다를 수 있음을 알기',ARRAY['6수03-07']::text[],1),
('M5-1-u6-C2','math',5,1,'u6',2,'다각형의 둘레 — 모든 변의 길이를 더해 구하고, 직사각형·평행사변형은 마주 보는 두 변이 같아 (이웃한 두 변의 합) × 2로 구하기(높이는 변이 아님)',ARRAY['6수03-07']::text[],2),
('M5-1-u6-C3','math',5,1,'u6',3,'마름모·정다각형의 둘레 — 변의 길이가 모두 같으므로 (한 변의 길이) × (변의 수)로 구하고, 둘레에서 한 변의 길이를 거꾸로 구하기',ARRAY['6수03-07']::text[],3),
('M5-1-u6-C4','math',5,1,'u6',5,'넓이의 단위 1 cm² — 한 변이 1 cm인 정사각형의 넓이를 1 cm²(1 제곱센티미터)로 약속한 까닭을 알고, 1 cm² 칸의 수로 넓이를 세기',ARRAY['6수03-08']::text[],4),
('M5-1-u6-C5','math',5,1,'u6',5,'직사각형·정사각형의 넓이 — 한 줄의 칸 수 × 줄의 수로 (가로) × (세로), (한 변) × (한 변)을 이해하고 넓이에서 변의 길이를 거꾸로 구하기',ARRAY['6수03-09']::text[],5),
('M5-1-u6-C6','math',5,1,'u6',6,'넓이의 단위 m²·km² — 1 m² = 10000 cm², 1 km² = 1000000 m²임을 가로·세로 두 방향의 배로 이해하고, 단위를 맞추어 넓이를 구하기',ARRAY['6수03-08']::text[],6),
('M5-1-u6-C7','math',5,1,'u6',7,'평행사변형의 넓이 — 밑변과 높이(두 밑변 사이의 수직 거리)를 알고, 잘라 옮겨 직사각형으로 바꾸어 (밑변의 길이) × (높이)로 구하기(이웃한 변이 아님)',ARRAY['6수03-09']::text[],7),
('M5-1-u6-C8','math',5,1,'u6',8,'삼각형의 넓이 — 밑변과 높이를 알고(높이가 삼각형 밖에 있을 수도 있음), 똑같은 삼각형 두 개로 평행사변형·직사각형을 만들어 (밑변의 길이) × (높이) ÷ 2로 구하기',ARRAY['6수03-09']::text[],8),
('M5-1-u6-C9','math',5,1,'u6',9,'사다리꼴의 넓이 — 윗변·아랫변·높이를 알고, 똑같은 사다리꼴 두 개로 평행사변형을 만들어 ((윗변) + (아랫변)) × (높이) ÷ 2로 구하며 나누어 구한 값과 같음을 알기',ARRAY['6수03-09']::text[],9),
('M5-1-u6-C10','math',5,1,'u6',10,'마름모의 넓이 — 마름모를 감싸는 직사각형의 가로·세로가 두 대각선임을 알고 그 절반인 (한 대각선) × (다른 대각선) ÷ 2로 구하기(둘레는 한 변, 넓이는 대각선)',ARRAY['6수03-09']::text[],10),
('M5-1-u6-C11','math',5,1,'u6',11,'여러 가지 방법으로 넓이 구하기 — 반듯하지 않은 도형을 아는 도형으로 나누어 더하거나 큰 도형에서 빼어 구하고, 겹치거나 빠뜨리지 않으면 어느 방법이든 답이 같음을 알기',ARRAY['6수03-09']::text[],11)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('M5-1-u6-X01','math',5,'u6',ARRAY['M5-1-u6-C1','M5-1-u6-C2','M5-1-u6-C5','M5-1-u6-C11']::text[],'둘레와 넓이를 섞는다 — 넓이를 (가로 + 세로) × 2로 구하거나 둘레를 가로 × 세로로 구하고, cm와 cm²를 가리지 않는다','가장자리 길이인지, 덮은 칸 수인지'),
('M5-1-u6-X02','math',5,'u6',ARRAY['M5-1-u6-C1','M5-1-u6-C4','M5-1-u6-C5']::text[],'둘레가 같으면 넓이도 같다고, 또는 둘레가 길면 넓이도 반드시 넓다고 여긴다','둘레가 같은 두 도형의 칸 세어 보기'),
('M5-1-u6-X03','math',5,'u6',ARRAY['M5-1-u6-C2','M5-1-u6-C3']::text[],'직사각형·평행사변형의 둘레에서 이웃한 두 변만 더하고 × 2를 빠뜨리거나, 둘레에서 한 변을 구할 때 2로 나누지 않는다','네 변을 손가락으로 하나씩 짚기'),
('M5-1-u6-X04','math',5,'u6',ARRAY['M5-1-u6-C2']::text[],'평행사변형의 둘레에 높이를 넣는다 — 높이는 변이 아니다','둘레는 가장자리만'),
('M5-1-u6-X05','math',5,'u6',ARRAY['M5-1-u6-C3']::text[],'정다각형의 둘레에서 변의 수를 잘못 쓴다 — 언제나 4를 곱하거나, 정오각형의 변을 4개·6개로 센다','이름 속 변의 수 확인'),
('M5-1-u6-X06','math',5,'u6',ARRAY['M5-1-u6-C4']::text[],'1 cm²를 둘레가 1 cm인 도형이나 가로가 1 cm인 도형의 넓이로 알거나, 크기가 다른 칸의 수로 넓이를 견준다','한 변 1 cm 정사각형 한 칸'),
('M5-1-u6-X07','math',5,'u6',ARRAY['M5-1-u6-C5','M5-1-u6-C6','M5-1-u6-C7','M5-1-u6-C10']::text[],'길이가 몇 배가 되면 넓이도 그만큼만 커진다고 여긴다 — 1 m² = 100 cm², 1 km² = 1000 m², 가로·세로를 2배 하면 넓이도 2배','가로도 세로도 늘어남'),
('M5-1-u6-X08','math',5,'u6',ARRAY['M5-1-u6-C6']::text[],'단위를 맞추지 않고 곱한다 — 200 cm × 1 m를 200 m²로','곱하기 전에 단위부터'),
('M5-1-u6-X09','math',5,'u6',ARRAY['M5-1-u6-C7']::text[],'평행사변형의 넓이를 밑변과 이웃한 변을 곱해 구한다','잘라 옮기면 세로는 높이'),
('M5-1-u6-X10','math',5,'u6',ARRAY['M5-1-u6-C8','M5-1-u6-C9','M5-1-u6-C10']::text[],'삼각형·사다리꼴·마름모의 넓이에서 ÷ 2를 빠뜨리거나, 평행사변형·직사각형에도 ÷ 2를 붙인다','둘을 붙였는지 생각하기'),
('M5-1-u6-X11','math',5,'u6',ARRAY['M5-1-u6-C7','M5-1-u6-C8','M5-1-u6-C9']::text[],'높이를 밑변에 수직이 아닌 선분(이웃한 변·대각선·빗변)으로 안다','밑변과 직각인 선분'),
('M5-1-u6-X12','math',5,'u6',ARRAY['M5-1-u6-C9']::text[],'사다리꼴의 넓이에서 윗변이나 아랫변 하나만 쓰거나, 윗변 + 아랫변 + 높이처럼 모두 더한다','윗변과 아랫변을 먼저 더하기'),
('M5-1-u6-X13','math',5,'u6',ARRAY['M5-1-u6-C10']::text[],'마름모의 넓이를 한 변 × 한 변이나 한 변 × 4로 구하거나, 두 대각선을 더한다','넓이는 두 대각선으로'),
('M5-1-u6-X14','math',5,'u6',ARRAY['M5-1-u6-C3','M5-1-u6-C5','M5-1-u6-C7','M5-1-u6-C8','M5-1-u6-C9','M5-1-u6-C10']::text[],'넓이·둘레에서 변이나 높이를 거꾸로 구할 때 곱셈과 나눗셈을 바꾸거나 ÷ 2를 되돌리지 않는다','공식에 □를 넣고 거꾸로'),
('M5-1-u6-X15','math',5,'u6',ARRAY['M5-1-u6-C2','M5-1-u6-C11']::text[],'나누어 더할 때 겹친 부분을 두 번 세거나 빠뜨리고, 빼야 할 부분을 더한다 — 붙인 변을 둘레에 넣기도 한다','겹침·빠짐 색칠해 보기'),
('M5-1-u6-X16','math',5,'u6',ARRAY['M5-1-u6-C1','M5-1-u6-C2','M5-1-u6-C3','M5-1-u6-C4','M5-1-u6-C5','M5-1-u6-C6','M5-1-u6-C7','M5-1-u6-C8','M5-1-u6-C9','M5-1-u6-C10','M5-1-u6-C11']::text[],'한 걸음의 셈(곱셈·나눗셈·덧셈)을 잘못한다','곱셈을 한 번 더 확인'),
('M5-1-u6-X17','math',5,'u6',ARRAY['M5-1-u6-C1','M5-1-u6-C2','M5-1-u6-C3','M5-1-u6-C4','M5-1-u6-C5','M5-1-u6-C6','M5-1-u6-C7','M5-1-u6-C8','M5-1-u6-C9','M5-1-u6-C10','M5-1-u6-C11']::text[],'묻는 말을 거꾸로 읽는다 — 잘못된↔옳은, 가장 넓은↔가장 좁은, 둘레↔넓이','물음의 「잘못·가장·둘레·넓이」에 동그라미')
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g5_1_math_u6_L02_basic#1','math',5,1,'u6','L02','g5_1_math_u6_L02_basic','lesson_basic','M5-1-u6-C1',1,'mc','auto','둘레는 무엇을 뜻하나요?',ARRAY['M5-1-u6-X01','M5-1-u6-X03','M5-1-u6-X16']::text[],true,'{"seq":1,"concept":"M5-1-u6-C1","difficulty":1,"kind":"mc","stem":"둘레는 무엇을 뜻하나요?","options":[{"t":"도형의 가장자리를 따라 잰 길이","correct":true},{"t":"도형 안쪽을 덮은 칸의 수","mis":"M5-1-u6-X01"},{"t":"가장 긴 변 하나의 길이","mis":"M5-1-u6-X03"},{"t":"변의 수","mis":"M5-1-u6-X16"}],"explanation":["게시판 가장자리에 두르는 색 띠지의 길이를 떠올려 봐요.","가장자리를 따라 한 바퀴 잰 길이가 둘레예요.","안쪽을 덮은 칸의 수는 넓이예요 — 둘은 다른 양이에요."],"variant_rule":{"alt":[{"stem":"넓이는 무엇을 뜻하나요?","options":[{"t":"같은 크기의 칸으로 안쪽을 덮은 칸의 수","correct":true},{"t":"가장자리를 따라 잰 길이","mis":"M5-1-u6-X01"},{"t":"가장 긴 변의 길이","mis":"M5-1-u6-X01"},{"t":"변의 수","mis":"M5-1-u6-X16"}],"explanation":["게시판 안쪽을 도화지로 덮는 것을 떠올려 봐요.","같은 크기의 칸으로 덮었을 때 칸이 몇 개인지가 넓이예요.","가장자리를 따라 잰 길이는 둘레예요."]},{"stem":"게시판 가장자리에 색 띠지를 두르려고 해요. 띠지가 얼마나 필요한지 알려면 무엇을 구해야 하나요?","options":[{"t":"게시판의 둘레","correct":true},{"t":"게시판의 넓이","mis":"M5-1-u6-X01"},{"t":"게시판 안쪽 칸의 수","mis":"M5-1-u6-X01"},{"t":"게시판 한 변의 길이","mis":"M5-1-u6-X03"}],"explanation":["띠지는 가장자리를 따라 둘러요.","가장자리를 따라 잰 길이가 둘레예요.","그래서 게시판의 둘레를 구해야 해요 — 넓이는 도화지로 덮을 때 필요해요."]}]}}'::jsonb),
('g5_1_math_u6_L02_basic#2','math',5,1,'u6','L02','g5_1_math_u6_L02_basic','lesson_basic','M5-1-u6-C2',1,'sa','auto','가로 7 cm, 세로 3 cm인 직사각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M5-1-u6-C2","difficulty":1,"kind":"sa","stem":"가로 7 cm, 세로 3 cm인 직사각형의 둘레는 몇 cm인가요?","answer":["20"],"explanation":["직사각형은 마주 보는 두 변의 길이가 같아요.","7 + 3 + 7 + 3 = 20이에요.","(7 + 3) × 2 = 20으로 구해도 돼요 — 둘레는 20 cm예요."],"variant_rule":{"alt":[{"stem":"가로 9 cm, 세로 4 cm인 직사각형의 둘레는 몇 cm인가요?","answer":["26"],"explanation":["직사각형은 마주 보는 두 변의 길이가 같아요.","9 + 4 + 9 + 4 = 26이에요.","(9 + 4) × 2 = 26으로 구해도 돼요 — 둘레는 26 cm예요."]},{"stem":"가로 12 m, 세로 5 m인 직사각형의 둘레는 몇 m인가요?","answer":["34"],"explanation":["직사각형은 마주 보는 두 변의 길이가 같아요.","12 + 5 + 12 + 5 = 34예요.","(12 + 5) × 2 = 34로 구해도 돼요 — 둘레는 34 m예요."]}]}}'::jsonb),
('g5_1_math_u6_L02_basic#3','math',5,1,'u6','L02','g5_1_math_u6_L02_basic','lesson_basic','M5-1-u6-C2',1,'mc','auto','다각형의 둘레를 구하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M5-1-u6-X05','M5-1-u6-X01','M5-1-u6-X16']::text[],true,'{"seq":3,"concept":"M5-1-u6-C2","difficulty":1,"kind":"mc","stem":"다각형의 둘레를 구하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"각 변의 길이를 모두 더한다","correct":true},{"t":"가장 긴 변을 변의 수만큼 곱한다","mis":"M5-1-u6-X05"},{"t":"가로와 세로를 곱한다","mis":"M5-1-u6-X01"},{"t":"변의 수를 센다","mis":"M5-1-u6-X16"}],"explanation":["둘레는 가장자리를 따라 잰 길이예요.","가장자리는 변들로 이어져 있어요.","그래서 각 변의 길이를 모두 더하면 둘레예요."],"variant_rule":{"alt":[{"stem":"가로 7 cm, 세로 3 cm인 직사각형의 둘레를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(7 + 3) × 2","correct":true},{"t":"7 × 3","mis":"M5-1-u6-X01"},{"t":"7 + 3","mis":"M5-1-u6-X03"},{"t":"7 × 3 ÷ 2","mis":"M5-1-u6-X10"}],"explanation":["직사각형은 가로와 세로가 각각 두 번씩 있어요.","7 + 3 + 7 + 3은 이웃한 두 변의 합을 2번 더한 것과 같아요.","그래서 (7 + 3) × 2 = 20으로 구해요."]},{"stem":"밑변 9 cm, 이웃한 변 4 cm인 평행사변형의 둘레를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(9 + 4) × 2","correct":true},{"t":"9 × 4","mis":"M5-1-u6-X01"},{"t":"9 + 4","mis":"M5-1-u6-X03"},{"t":"9 × 2 + 4","mis":"M5-1-u6-X03"}],"explanation":["평행사변형도 마주 보는 두 변의 길이가 같아요.","네 변은 9 cm, 4 cm, 9 cm, 4 cm예요.","그래서 (9 + 4) × 2 = 26으로 구해요."]}]}}'::jsonb),
('g5_1_math_u6_L02_basic#4','math',5,1,'u6','L02','g5_1_math_u6_L02_basic','lesson_basic','M5-1-u6-C2',1,'sa','auto','체험 학습 깃발의 삼각형 부분이에요. 세 변의 길이가 30 cm, 22 cm, 30 cm일 때 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":4,"concept":"M5-1-u6-C2","difficulty":1,"kind":"sa","stem":"체험 학습 깃발의 삼각형 부분이에요. 세 변의 길이가 30 cm, 22 cm, 30 cm일 때 둘레는 몇 cm인가요?","answer":["82"],"explanation":["다각형의 둘레는 모든 변의 길이의 합이에요.","30 + 22 + 30 = 82예요.","그래서 둘레는 82 cm예요."],"variant_rule":{"alt":[{"stem":"체험 학습 깃발의 삼각형 부분이에요. 세 변의 길이가 25 cm, 18 cm, 25 cm일 때 둘레는 몇 cm인가요?","answer":["68"],"explanation":["다각형의 둘레는 모든 변의 길이의 합이에요.","25 + 18 + 25 = 68이에요.","그래서 둘레는 68 cm예요."]},{"stem":"체험 학습 깃발의 사각형 부분이에요. 네 변의 길이가 22 cm, 16 cm, 22 cm, 16 cm일 때 둘레는 몇 cm인가요?","answer":["76"],"explanation":["다각형의 둘레는 모든 변의 길이의 합이에요.","22 + 16 + 22 + 16 = 76이에요.","그래서 둘레는 76 cm예요."]}]}}'::jsonb),
('g5_1_math_u6_L02_basic#5','math',5,1,'u6','L02','g5_1_math_u6_L02_basic','lesson_basic','M5-1-u6-C1',2,'mc','auto','모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 그림의 직사각형의 넓이는 몇 cm²인가요?',ARRAY['M5-1-u6-X01','M5-1-u6-X16']::text[],true,'{"seq":5,"concept":"M5-1-u6-C1","difficulty":2,"kind":"mc","stem":"모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 그림의 직사각형의 넓이는 몇 cm²인가요?","options":[{"t":"21 cm²","correct":true},{"t":"20 cm²","mis":"M5-1-u6-X01"},{"t":"10 cm²","mis":"M5-1-u6-X01"},{"t":"28 cm²","mis":"M5-1-u6-X16"}],"explanation":["한 줄에 7칸씩, 그런 줄이 3줄 있어요.","7 × 3 = 21 — 모두 21칸이에요.","한 칸이 1 cm²니 넓이는 21 cm²예요. 20 cm는 둘레예요."],"asset":{"type":"geo","items":[{"w":135,"h":75,"grid":15,"poly":[[[15,15],[120,15],[120,60],[15,60]]],"show":[]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 그림의 직사각형의 넓이는 몇 cm²인가요?","options":[{"t":"20 cm²","correct":true},{"t":"18 cm²","mis":"M5-1-u6-X01"},{"t":"9 cm²","mis":"M5-1-u6-X01"},{"t":"25 cm²","mis":"M5-1-u6-X16"}],"explanation":["한 줄에 5칸씩, 그런 줄이 4줄 있어요.","5 × 4 = 20 — 모두 20칸이에요.","한 칸이 1 cm²니 넓이는 20 cm²예요. 18 cm는 둘레예요."],"asset":{"type":"geo","items":[{"w":105,"h":90,"grid":15,"poly":[[[15,15],[90,15],[90,75],[15,75]]],"show":[]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 그림의 직사각형의 넓이는 몇 cm²인가요?","options":[{"t":"12 cm²","correct":true},{"t":"16 cm²","mis":"M5-1-u6-X01"},{"t":"8 cm²","mis":"M5-1-u6-X01"},{"t":"18 cm²","mis":"M5-1-u6-X16"}],"explanation":["한 줄에 6칸씩, 그런 줄이 2줄 있어요.","6 × 2 = 12 — 모두 12칸이에요.","한 칸이 1 cm²니 넓이는 12 cm²예요. 16 cm는 둘레예요."],"asset":{"type":"geo","items":[{"w":120,"h":60,"grid":15,"poly":[[[15,15],[105,15],[105,45],[15,45]]],"show":[]}],"tag":false}}]}}'::jsonb),
('g5_1_math_u6_L02_basic#6','math',5,1,'u6','L02','g5_1_math_u6_L02_basic','lesson_basic','M5-1-u6-C2',2,'sa','auto','평행사변형의 밑변이 8 cm, 이웃한 변이 4 cm예요. 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M5-1-u6-C2","difficulty":2,"kind":"sa","stem":"평행사변형의 밑변이 8 cm, 이웃한 변이 4 cm예요. 둘레는 몇 cm인가요?","answer":["24"],"explanation":["평행사변형은 마주 보는 두 변의 길이가 같아요.","8 + 4 + 8 + 4 = 24예요.","(8 + 4) × 2 = 24 — 둘레는 24 cm예요."],"variant_rule":{"alt":[{"stem":"평행사변형의 밑변이 12 m, 이웃한 변이 3 m예요. 둘레는 몇 m인가요?","answer":["30"],"explanation":["평행사변형은 마주 보는 두 변의 길이가 같아요.","12 + 3 + 12 + 3 = 30이에요.","(12 + 3) × 2 = 30 — 둘레는 30 m예요."]},{"stem":"평행사변형의 밑변이 9 cm, 이웃한 변이 5 cm예요. 둘레는 몇 cm인가요?","answer":["28"],"explanation":["평행사변형은 마주 보는 두 변의 길이가 같아요.","9 + 5 + 9 + 5 = 28이에요.","(9 + 5) × 2 = 28 — 둘레는 28 cm예요."]}]}}'::jsonb),
('g5_1_math_u6_L02_basic#7','math',5,1,'u6','L02','g5_1_math_u6_L02_basic','lesson_basic','M5-1-u6-C2',2,'mc','auto','밑변 8 cm, 이웃한 변 5 cm, 높이 3 cm인 평행사변형이에요. 둘레를 구하는 식으로 잘못된 것은 어느 것인가요?',ARRAY['M5-1-u6-X17']::text[],true,'{"seq":7,"concept":"M5-1-u6-C2","difficulty":2,"kind":"mc","stem":"밑변 8 cm, 이웃한 변 5 cm, 높이 3 cm인 평행사변형이에요. 둘레를 구하는 식으로 잘못된 것은 어느 것인가요?","options":[{"t":"(8 + 3) × 2","correct":true},{"t":"8 + 5 + 8 + 5","mis":"M5-1-u6-X17"},{"t":"(8 + 5) × 2","mis":"M5-1-u6-X17"},{"t":"8 × 2 + 5 × 2","mis":"M5-1-u6-X17"}],"explanation":["둘레는 가장자리를 이루는 네 변의 길이의 합이에요.","높이 3 cm는 두 밑변 사이의 거리라 가장자리가 아니에요.","그래서 높이를 넣은 (8 + 3) × 2가 잘못된 식이에요 — 바른 둘레는 26 cm예요."],"variant_rule":{"alt":[{"stem":"밑변 10 cm, 이웃한 변 6 cm, 높이 4 cm인 평행사변형이에요. 둘레를 구하는 식으로 잘못된 것은 어느 것인가요?","options":[{"t":"(10 + 4) × 2","correct":true},{"t":"10 + 6 + 10 + 6","mis":"M5-1-u6-X17"},{"t":"(10 + 6) × 2","mis":"M5-1-u6-X17"},{"t":"10 × 2 + 6 × 2","mis":"M5-1-u6-X17"}],"explanation":["둘레는 가장자리를 이루는 네 변의 길이의 합이에요.","높이 4 cm는 두 밑변 사이의 거리라 가장자리가 아니에요.","그래서 높이를 넣은 (10 + 4) × 2가 잘못된 식이에요 — 바른 둘레는 32 cm예요."]},{"stem":"밑변 7 cm, 이웃한 변 4 cm, 높이 3 cm인 평행사변형이에요. 둘레를 구하는 식으로 잘못된 것은 어느 것인가요?","options":[{"t":"(7 + 3) × 2","correct":true},{"t":"7 + 4 + 7 + 4","mis":"M5-1-u6-X17"},{"t":"(7 + 4) × 2","mis":"M5-1-u6-X17"},{"t":"7 × 2 + 4 × 2","mis":"M5-1-u6-X17"}],"explanation":["둘레는 가장자리를 이루는 네 변의 길이의 합이에요.","높이 3 cm는 두 밑변 사이의 거리라 가장자리가 아니에요.","그래서 높이를 넣은 (7 + 3) × 2가 잘못된 식이에요 — 바른 둘레는 22 cm예요."]}]}}'::jsonb),
('g5_1_math_u6_L02_basic#8','math',5,1,'u6','L02','g5_1_math_u6_L02_basic','lesson_basic','M5-1-u6-C1',2,'ox','auto','둘레가 같은 두 직사각형은 넓이도 반드시 같아요.',ARRAY['M5-1-u6-X02']::text[],true,'{"seq":8,"concept":"M5-1-u6-C1","difficulty":2,"kind":"ox","stem":"둘레가 같은 두 직사각형은 넓이도 반드시 같아요.","answer":"X","reason_options":[{"t":"둘레가 20 cm로 같아도 5 × 5 = 25, 9 × 1 = 9로 넓이가 다르므로","correct":true},{"t":"둘레가 같으면 가로와 세로도 같으므로","mis":"M5-1-u6-X02"}],"mis":"M5-1-u6-X02","explanation":["가로 5 cm, 세로 5 cm인 정사각형과 가로 9 cm, 세로 1 cm인 직사각형은 둘레가 모두 20 cm예요.","넓이는 5 × 5 = 25, 9 × 1 = 9예요.","둘레가 같아도 넓이는 다를 수 있어요."],"variant_rule":{"alt":[{"stem":"둘레가 더 긴 도형이 넓이도 언제나 더 넓어요.","answer":"X","reason_options":[{"t":"둘레 20 cm인 9 × 1 직사각형은 둘레 16 cm인 5 × 3 직사각형보다 좁으므로","correct":true},{"t":"가장자리가 길면 안쪽도 늘 넓어지므로","mis":"M5-1-u6-X02"}],"explanation":["가로 9 cm, 세로 1 cm인 직사각형은 둘레 20 cm, 넓이 9 cm²예요.","가로 5 cm, 세로 3 cm인 직사각형은 둘레 16 cm, 넓이 15 cm²예요.","둘레가 더 긴 쪽이 오히려 좁아요 — 둘레와 넓이는 다른 양이에요."]},{"stem":"둘레는 cm로, 넓이는 cm²로 나타내요.","answer":"O","reason_options":[{"t":"둘레는 길이이고 넓이는 칸의 수라 재는 것이 다르므로","correct":true},{"t":"둘레가 넓이보다 늘 작으므로","mis":"M5-1-u6-X01"}],"explanation":["둘레는 가장자리를 따라 잰 길이예요.","넓이는 한 변이 1 cm인 칸이 몇 개인지예요.","재는 것이 달라 단위도 cm와 cm²로 달라요."]}]}}'::jsonb),
('g5_1_math_u6_L02_basic#9','math',5,1,'u6','L02','g5_1_math_u6_L02_basic','lesson_basic','M5-1-u6-C2',2,'mc','auto','둘레가 더 긴 것은 어느 것인가요? ㉠ 가로 9 cm, 세로 4 cm인 직사각형 ㉡ 밑변 7 cm, 이웃한 변 5 cm인 평행사변형',ARRAY['M5-1-u6-X16','M5-1-u6-X02','M5-1-u6-X04']::text[],true,'{"seq":9,"concept":"M5-1-u6-C2","difficulty":2,"kind":"mc","stem":"둘레가 더 긴 것은 어느 것인가요? ㉠ 가로 9 cm, 세로 4 cm인 직사각형 ㉡ 밑변 7 cm, 이웃한 변 5 cm인 평행사변형","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"M5-1-u6-X16"},{"t":"두 둘레가 같다","mis":"M5-1-u6-X02"},{"t":"알 수 없다","mis":"M5-1-u6-X04"}],"explanation":["㉠의 둘레는 (9 + 4) × 2 = 26이에요.","㉡의 둘레는 (7 + 5) × 2 = 24예요.","26 cm와 24 cm를 견주면 ㉠의 둘레가 더 길어요."],"variant_rule":{"alt":[{"stem":"둘레가 더 긴 것은 어느 것인가요? ㉠ 가로 6 cm, 세로 6 cm인 직사각형 ㉡ 밑변 8 cm, 이웃한 변 3 cm인 평행사변형","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"M5-1-u6-X16"},{"t":"두 둘레가 같다","mis":"M5-1-u6-X02"},{"t":"알 수 없다","mis":"M5-1-u6-X04"}],"explanation":["㉠의 둘레는 (6 + 6) × 2 = 24예요.","㉡의 둘레는 (8 + 3) × 2 = 22예요.","24 cm와 22 cm를 견주면 ㉠의 둘레가 더 길어요."]},{"stem":"둘레가 더 긴 것은 어느 것인가요? ㉠ 가로 10 cm, 세로 2 cm인 직사각형 ㉡ 밑변 7 cm, 이웃한 변 4 cm인 평행사변형","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"M5-1-u6-X16"},{"t":"두 둘레가 같다","mis":"M5-1-u6-X02"},{"t":"알 수 없다","mis":"M5-1-u6-X04"}],"explanation":["㉠의 둘레는 (10 + 2) × 2 = 24예요.","㉡의 둘레는 (7 + 4) × 2 = 22예요.","24 cm와 22 cm를 견주면 ㉠의 둘레가 더 길어요."]}]}}'::jsonb),
('g5_1_math_u6_L02_basic#10','math',5,1,'u6','L02','g5_1_math_u6_L02_basic','lesson_basic','M5-1-u6-C2',3,'sa','auto','둘레가 34 cm인 직사각형의 가로가 11 cm예요. 세로는 몇 cm인가요?','{}'::text[],true,'{"seq":10,"concept":"M5-1-u6-C2","difficulty":3,"kind":"sa","stem":"둘레가 34 cm인 직사각형의 가로가 11 cm예요. 세로는 몇 cm인가요?","answer":["6"],"explanation":["직사각형의 둘레는 (가로 + 세로) × 2예요.","가로 + 세로 = 34 ÷ 2 = 17이에요.","세로 = 17 − 11 = 6 — 세로는 6 cm예요."],"mis":"M5-1-u6-X03","variant_rule":{"alt":[{"stem":"둘레가 40 cm인 직사각형의 가로가 12 cm예요. 세로는 몇 cm인가요?","answer":["8"],"explanation":["직사각형의 둘레는 (가로 + 세로) × 2예요.","가로 + 세로 = 40 ÷ 2 = 20이에요.","세로 = 20 − 12 = 8 — 세로는 8 cm예요."]},{"stem":"둘레가 26 cm인 직사각형의 가로가 8 cm예요. 세로는 몇 cm인가요?","answer":["5"],"explanation":["직사각형의 둘레는 (가로 + 세로) × 2예요.","가로 + 세로 = 26 ÷ 2 = 13이에요.","세로 = 13 − 8 = 5 — 세로는 5 cm예요."]}]}}'::jsonb),
('g5_1_math_u6_L02_challenge#1','math',5,1,'u6','L02','g5_1_math_u6_L02_challenge','lesson_challenge','M5-1-u6-C2',2,'error','auto','가로 7 cm, 세로 3 cm인 직사각형의 둘레를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u6-X03','M5-1-u6-X17']::text[],true,'{"seq":1,"concept":"M5-1-u6-C2","difficulty":2,"kind":"error","stem":"가로 7 cm, 세로 3 cm인 직사각형의 둘레를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「가로와 세로를 더한 10 cm가 둘레야.」","correct":true,"mis_target":"M5-1-u6-X03"},{"t":"도현 — 「7 + 3 + 7 + 3으로 구하면 돼.」","mis":"M5-1-u6-X17"},{"t":"하은 — 「(7 + 3) × 2로 구해도 같아.」","mis":"M5-1-u6-X17"}],"explanation":["직사각형의 변은 네 개예요.","가로와 세로를 한 번씩만 더하면 두 변의 길이뿐이에요.","서윤은 두 변만 더해 잘못 말했어요 — 둘레는 (7 + 3) × 2 = 20이에요."],"variant_rule":{"alt":[{"stem":"가로 9 cm, 세로 5 cm인 직사각형의 둘레를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「가로와 세로를 더한 14 cm가 둘레야.」","correct":true,"mis_target":"M5-1-u6-X03"},{"t":"라온 — 「9 + 5 + 9 + 5로 구하면 돼.」","mis":"M5-1-u6-X17"},{"t":"예준 — 「(9 + 5) × 2로 구해도 같아.」","mis":"M5-1-u6-X17"}],"explanation":["직사각형의 변은 네 개예요.","가로와 세로를 한 번씩만 더하면 두 변의 길이뿐이에요.","지민은 두 변만 더해 잘못 말했어요 — 둘레는 (9 + 5) × 2 = 28이에요."]},{"stem":"가로 8 cm, 세로 6 cm인 직사각형의 둘레를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤아 — 「가로와 세로를 더한 14 cm가 둘레야.」","correct":true,"mis_target":"M5-1-u6-X03"},{"t":"시우 — 「8 + 6 + 8 + 6으로 구하면 돼.」","mis":"M5-1-u6-X17"},{"t":"나린 — 「(8 + 6) × 2로 구해도 같아.」","mis":"M5-1-u6-X17"}],"explanation":["직사각형의 변은 네 개예요.","가로와 세로를 한 번씩만 더하면 두 변의 길이뿐이에요.","윤아는 두 변만 더해 잘못 말했어요 — 둘레는 (8 + 6) × 2 = 28이에요."]}]}}'::jsonb),
('g5_1_math_u6_L02_challenge#2','math',5,1,'u6','L02','g5_1_math_u6_L02_challenge','lesson_challenge','M5-1-u6-C1',2,'mc','auto','둘레가 모두 20 cm인 직사각형들이에요. 넓이가 가장 넓은 것은 어느 것인가요?',ARRAY['M5-1-u6-X02']::text[],true,'{"seq":2,"concept":"M5-1-u6-C1","difficulty":2,"kind":"mc","stem":"둘레가 모두 20 cm인 직사각형들이에요. 넓이가 가장 넓은 것은 어느 것인가요?","options":[{"t":"가로 5 cm · 세로 5 cm","correct":true},{"t":"가로 6 cm · 세로 4 cm","mis":"M5-1-u6-X02"},{"t":"가로 9 cm · 세로 1 cm","mis":"M5-1-u6-X02"},{"t":"가로 7 cm · 세로 3 cm","mis":"M5-1-u6-X02"}],"explanation":["네 직사각형은 모두 가로 + 세로 = 10이라 둘레가 20 cm예요.","넓이는 6 × 4 = 24, 9 × 1 = 9, 7 × 3 = 21, 5 × 5 = 25예요.","둘레가 같아도 넓이는 달라요 — 가장 넓은 것은 가로 5 cm · 세로 5 cm예요."],"variant_rule":{"alt":[{"stem":"둘레가 모두 20 cm인 직사각형들이에요. 넓이가 가장 좁은 것은 어느 것인가요?","options":[{"t":"가로 9 cm · 세로 1 cm","correct":true},{"t":"가로 6 cm · 세로 4 cm","mis":"M5-1-u6-X02"},{"t":"가로 7 cm · 세로 3 cm","mis":"M5-1-u6-X02"},{"t":"가로 5 cm · 세로 5 cm","mis":"M5-1-u6-X02"}],"explanation":["네 직사각형은 모두 가로 + 세로 = 10이라 둘레가 20 cm예요.","넓이는 6 × 4 = 24, 9 × 1 = 9, 7 × 3 = 21, 5 × 5 = 25예요.","둘레가 같아도 넓이는 달라요 — 가장 좁은 것은 가로 9 cm · 세로 1 cm예요."]},{"stem":"둘레가 모두 24 cm인 직사각형들이에요. 넓이가 가장 넓은 것은 어느 것인가요?","options":[{"t":"가로 6 cm · 세로 6 cm","correct":true},{"t":"가로 7 cm · 세로 5 cm","mis":"M5-1-u6-X02"},{"t":"가로 11 cm · 세로 1 cm","mis":"M5-1-u6-X02"},{"t":"가로 9 cm · 세로 3 cm","mis":"M5-1-u6-X02"}],"explanation":["네 직사각형은 모두 가로 + 세로 = 12라 둘레가 24 cm예요.","넓이는 7 × 5 = 35, 11 × 1 = 11, 9 × 3 = 27, 6 × 6 = 36이에요.","둘레가 같아도 넓이는 달라요 — 가장 넓은 것은 가로 6 cm · 세로 6 cm예요."]}]}}'::jsonb),
('g5_1_math_u6_L02_challenge#3','math',5,1,'u6','L02','g5_1_math_u6_L02_challenge','lesson_challenge','M5-1-u6-C1',3,'sa','auto','둘레가 20 cm인 직사각형의 가로가 9 cm예요. 이 직사각형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":3,"concept":"M5-1-u6-C1","difficulty":3,"kind":"sa","stem":"둘레가 20 cm인 직사각형의 가로가 9 cm예요. 이 직사각형의 넓이는 몇 cm²인가요?","answer":["9"],"explanation":["가로 + 세로 = 20 ÷ 2 = 10이에요.","세로 = 10 − 9 = 1이에요.","넓이는 9 × 1 = 9 — 9 cm²예요."],"mis":"M5-1-u6-X01","variant_rule":{"alt":[{"stem":"둘레가 24 cm인 직사각형의 가로가 10 cm예요. 이 직사각형의 넓이는 몇 cm²인가요?","answer":["20"],"explanation":["가로 + 세로 = 24 ÷ 2 = 12예요.","세로 = 12 − 10 = 2예요.","넓이는 10 × 2 = 20 — 20 cm²예요."]},{"stem":"둘레가 18 cm인 직사각형의 가로가 7 cm예요. 이 직사각형의 넓이는 몇 cm²인가요?","answer":["14"],"explanation":["가로 + 세로 = 18 ÷ 2 = 9예요.","세로 = 9 − 7 = 2예요.","넓이는 7 × 2 = 14 — 14 cm²예요."]}]}}'::jsonb),
('g5_1_math_u6_L02_challenge#4','math',5,1,'u6','L02','g5_1_math_u6_L02_challenge','lesson_challenge','M5-1-u6-C2',3,'sa','auto','가로가 세로보다 4 cm 더 긴 직사각형의 둘레가 32 cm예요. 세로는 몇 cm인가요?','{}'::text[],true,'{"seq":4,"concept":"M5-1-u6-C2","difficulty":3,"kind":"sa","stem":"가로가 세로보다 4 cm 더 긴 직사각형의 둘레가 32 cm예요. 세로는 몇 cm인가요?","answer":["6"],"explanation":["가로 + 세로 = 32 ÷ 2 = 16이에요.","세로를 □라 하면 □ + □ + 4 = 16이라 □ + □ = 12예요.","□ = 12 ÷ 2 = 6 — 세로는 6 cm, 가로는 10 cm예요."],"mis":"M5-1-u6-X03","variant_rule":{"alt":[{"stem":"가로가 세로보다 2 cm 더 긴 직사각형의 둘레가 28 cm예요. 세로는 몇 cm인가요?","answer":["6"],"explanation":["가로 + 세로 = 28 ÷ 2 = 14예요.","세로를 □라 하면 □ + □ + 2 = 14라 □ + □ = 12예요.","□ = 12 ÷ 2 = 6 — 세로는 6 cm, 가로는 8 cm예요."]},{"stem":"가로가 세로보다 6 cm 더 긴 직사각형의 둘레가 40 cm예요. 세로는 몇 cm인가요?","answer":["7"],"explanation":["가로 + 세로 = 40 ÷ 2 = 20이에요.","세로를 □라 하면 □ + □ + 6 = 20이라 □ + □ = 14예요.","□ = 14 ÷ 2 = 7 — 세로는 7 cm, 가로는 13 cm예요."]}]}}'::jsonb),
('g5_1_math_u6_L02_challenge#5','math',5,1,'u6','L02','g5_1_math_u6_L02_challenge','lesson_challenge','M5-1-u6-C2',3,'mc','auto','가로 8 cm, 세로 5 cm인 직사각형 카드 2장을 가로로 겹치지 않게 나란히 이어 붙여 큰 직사각형을 만들었어요. 큰 직사각형의 둘레는 몇 cm인가요?',ARRAY['M5-1-u6-X15','M5-1-u6-X16','M5-1-u6-X03']::text[],true,'{"seq":5,"concept":"M5-1-u6-C2","difficulty":3,"kind":"mc","stem":"가로 8 cm, 세로 5 cm인 직사각형 카드 2장을 가로로 겹치지 않게 나란히 이어 붙여 큰 직사각형을 만들었어요. 큰 직사각형의 둘레는 몇 cm인가요?","options":[{"t":"42 cm","correct":true},{"t":"52 cm","mis":"M5-1-u6-X15"},{"t":"26 cm","mis":"M5-1-u6-X16"},{"t":"21 cm","mis":"M5-1-u6-X03"}],"explanation":["이어 붙이면 큰 직사각형의 가로는 8 × 2 = 16, 세로는 5예요.","맞붙은 변은 안쪽으로 들어가 가장자리가 아니에요.","(16 + 5) × 2 = 42 — 둘레는 42 cm예요."],"variant_rule":{"alt":[{"stem":"가로 6 cm, 세로 4 cm인 직사각형 카드 3장을 가로로 겹치지 않게 나란히 이어 붙여 큰 직사각형을 만들었어요. 큰 직사각형의 둘레는 몇 cm인가요?","options":[{"t":"44 cm","correct":true},{"t":"60 cm","mis":"M5-1-u6-X15"},{"t":"20 cm","mis":"M5-1-u6-X16"},{"t":"22 cm","mis":"M5-1-u6-X03"}],"explanation":["이어 붙이면 큰 직사각형의 가로는 6 × 3 = 18, 세로는 4예요.","맞붙은 변은 안쪽으로 들어가 가장자리가 아니에요.","(18 + 4) × 2 = 44 — 둘레는 44 cm예요."]},{"stem":"가로 5 cm, 세로 3 cm인 직사각형 카드 2장을 가로로 겹치지 않게 나란히 이어 붙여 큰 직사각형을 만들었어요. 큰 직사각형의 둘레는 몇 cm인가요?","options":[{"t":"26 cm","correct":true},{"t":"32 cm","mis":"M5-1-u6-X15"},{"t":"16 cm","mis":"M5-1-u6-X16"},{"t":"13 cm","mis":"M5-1-u6-X03"}],"explanation":["이어 붙이면 큰 직사각형의 가로는 5 × 2 = 10, 세로는 3이에요.","맞붙은 변은 안쪽으로 들어가 가장자리가 아니에요.","(10 + 3) × 2 = 26 — 둘레는 26 cm예요."]}]}}'::jsonb),
('g5_1_math_u6_L02_challenge#6','math',5,1,'u6','L02','g5_1_math_u6_L02_challenge','lesson_challenge','M5-1-u6-C1',3,'mc','auto','모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 두 직사각형 ㉮와 ㉯ 가운데 넓이가 더 넓은 것은 어느 것인가요?',ARRAY['M5-1-u6-X02','M5-1-u6-X06']::text[],true,'{"seq":6,"concept":"M5-1-u6-C1","difficulty":3,"kind":"mc","stem":"모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 두 직사각형 ㉮와 ㉯ 가운데 넓이가 더 넓은 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M5-1-u6-X02"},{"t":"두 넓이가 같다","mis":"M5-1-u6-X02"},{"t":"알 수 없다","mis":"M5-1-u6-X06"}],"explanation":["㉮는 가로 6칸, 세로 2칸 — 둘레 (6 + 2) × 2 = 16, 넓이 6 × 2 = 12예요.","㉯는 가로 4칸, 세로 4칸 — 둘레 (4 + 4) × 2 = 16, 넓이 4 × 4 = 16이에요.","둘레는 16 cm로 같지만 넓이는 달라요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[15,15],[105,15],[105,45],[15,45]]],"show":[]},{"w":120,"h":90,"grid":15,"poly":[[[15,15],[75,15],[75,75],[15,75]]],"show":[]}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 두 직사각형 ㉮와 ㉯ 가운데 넓이가 더 넓은 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M5-1-u6-X02"},{"t":"두 넓이가 같다","mis":"M5-1-u6-X02"},{"t":"알 수 없다","mis":"M5-1-u6-X06"}],"explanation":["㉮는 가로 7칸, 세로 1칸 — 둘레 (7 + 1) × 2 = 16, 넓이 7 × 1 = 7이에요.","㉯는 가로 5칸, 세로 3칸 — 둘레 (5 + 3) × 2 = 16, 넓이 5 × 3 = 15예요.","둘레는 16 cm로 같지만 넓이는 달라요."],"asset":{"type":"geo","items":[{"w":135,"h":75,"grid":15,"poly":[[[15,15],[120,15],[120,30],[15,30]]],"show":[]},{"w":135,"h":75,"grid":15,"poly":[[[15,15],[90,15],[90,60],[15,60]]],"show":[]}]}},{"stem":"모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 두 직사각형 ㉮와 ㉯의 둘레를 견주면 어떠한가요?","options":[{"t":"두 둘레가 같다","correct":true},{"t":"㉮의 둘레가 더 길다","mis":"M5-1-u6-X02"},{"t":"㉯의 둘레가 더 길다","mis":"M5-1-u6-X02"},{"t":"알 수 없다","mis":"M5-1-u6-X06"}],"explanation":["㉮는 가로 6칸, 세로 3칸 — 둘레 (6 + 3) × 2 = 18, 넓이 6 × 3 = 18이에요.","㉯는 가로 5칸, 세로 4칸 — 둘레 (5 + 4) × 2 = 18, 넓이 5 × 4 = 20이에요.","둘레는 18 cm로 같지만 넓이는 달라요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[15,15],[105,15],[105,60],[15,60]]],"show":[]},{"w":120,"h":90,"grid":15,"poly":[[[15,15],[90,15],[90,75],[15,75]]],"show":[]}]}}]}}'::jsonb),
('g5_1_math_u6_L02_challenge#7','math',5,1,'u6','L02','g5_1_math_u6_L02_challenge','lesson_challenge','M5-1-u6-C2',3,'sa','auto','둘레가 30 cm인 평행사변형의 밑변이 9 cm예요. 이웃한 변은 몇 cm인가요?','{}'::text[],true,'{"seq":7,"concept":"M5-1-u6-C2","difficulty":3,"kind":"sa","stem":"둘레가 30 cm인 평행사변형의 밑변이 9 cm예요. 이웃한 변은 몇 cm인가요?","answer":["6"],"explanation":["평행사변형의 둘레는 (밑변 + 이웃한 변) × 2예요.","밑변 + 이웃한 변 = 30 ÷ 2 = 15예요.","이웃한 변 = 15 − 9 = 6 — 6 cm예요."],"mis":"M5-1-u6-X03","variant_rule":{"alt":[{"stem":"둘레가 36 cm인 평행사변형의 밑변이 11 cm예요. 이웃한 변은 몇 cm인가요?","answer":["7"],"explanation":["평행사변형의 둘레는 (밑변 + 이웃한 변) × 2예요.","밑변 + 이웃한 변 = 36 ÷ 2 = 18이에요.","이웃한 변 = 18 − 11 = 7 — 7 cm예요."]},{"stem":"둘레가 44 cm인 평행사변형의 밑변이 15 cm예요. 이웃한 변은 몇 cm인가요?","answer":["7"],"explanation":["평행사변형의 둘레는 (밑변 + 이웃한 변) × 2예요.","밑변 + 이웃한 변 = 44 ÷ 2 = 22예요.","이웃한 변 = 22 − 15 = 7 — 7 cm예요."]}]}}'::jsonb),
('g5_1_math_u6_L02_challenge#8','math',5,1,'u6','L02','g5_1_math_u6_L02_challenge','lesson_challenge','M5-1-u6-C1',4,'sa','auto','둘레가 20 cm인 직사각형 가운데 가로와 세로가 자연수(cm)인 것을 모두 생각해요. 넓이가 가장 넓은 것의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":8,"concept":"M5-1-u6-C1","difficulty":4,"kind":"sa","stem":"둘레가 20 cm인 직사각형 가운데 가로와 세로가 자연수(cm)인 것을 모두 생각해요. 넓이가 가장 넓은 것의 넓이는 몇 cm²인가요?","answer":["25"],"explanation":["가로 + 세로 = 20 ÷ 2 = 10이에요.","가로와 세로가 가까울수록 넓이가 넓어져요 — 1 × 9 = 9, 2 × 8 = 16, 3 × 7 = 21, 5 × 5 = 25예요.","가장 넓은 것은 가로와 세로가 같은 5 × 5 = 25 — 25 cm²예요."],"mis":"M5-1-u6-X02","variant_rule":{"alt":[{"stem":"둘레가 24 cm인 직사각형 가운데 가로와 세로가 자연수(cm)인 것을 모두 생각해요. 넓이가 가장 넓은 것의 넓이는 몇 cm²인가요?","answer":["36"],"explanation":["가로 + 세로 = 24 ÷ 2 = 12예요.","가로와 세로가 가까울수록 넓이가 넓어져요 — 1 × 11 = 11, 2 × 10 = 20, 3 × 9 = 27, 6 × 6 = 36이에요.","가장 넓은 것은 가로와 세로가 같은 6 × 6 = 36 — 36 cm²예요."]},{"stem":"둘레가 28 cm인 직사각형 가운데 가로와 세로가 자연수(cm)인 것을 모두 생각해요. 넓이가 가장 넓은 것의 넓이는 몇 cm²인가요?","answer":["49"],"explanation":["가로 + 세로 = 28 ÷ 2 = 14예요.","가로와 세로가 가까울수록 넓이가 넓어져요 — 1 × 13 = 13, 2 × 12 = 24, 3 × 11 = 33, 7 × 7 = 49예요.","가장 넓은 것은 가로와 세로가 같은 7 × 7 = 49 — 49 cm²예요."]}]}}'::jsonb),
('g5_1_math_u6_L02_challenge#9','math',5,1,'u6','L02','g5_1_math_u6_L02_challenge','lesson_challenge','M5-1-u6-C2',4,'mc','auto','한 변이 6 cm인 정사각형 색종이를 똑같은 직사각형 두 개가 되도록 반으로 잘랐어요. 잘라 낸 직사각형 한 개의 둘레는 몇 cm인가요?',ARRAY['M5-1-u6-X15','M5-1-u6-X03']::text[],true,'{"seq":9,"concept":"M5-1-u6-C2","difficulty":4,"kind":"mc","stem":"한 변이 6 cm인 정사각형 색종이를 똑같은 직사각형 두 개가 되도록 반으로 잘랐어요. 잘라 낸 직사각형 한 개의 둘레는 몇 cm인가요?","options":[{"t":"18 cm","correct":true},{"t":"12 cm","mis":"M5-1-u6-X15"},{"t":"24 cm","mis":"M5-1-u6-X15"},{"t":"15 cm","mis":"M5-1-u6-X03"}],"explanation":["반으로 자른 직사각형은 가로 6 cm, 세로 3 cm예요.","자른 자리도 새 변이 되어 둘레에 들어가요.","(6 + 3) × 2 = 18 — 둘레는 18 cm예요. 정사각형 둘레 24의 절반이 아니에요."],"variant_rule":{"alt":[{"stem":"한 변이 8 cm인 정사각형 색종이를 똑같은 직사각형 두 개가 되도록 반으로 잘랐어요. 잘라 낸 직사각형 한 개의 둘레는 몇 cm인가요?","options":[{"t":"24 cm","correct":true},{"t":"16 cm","mis":"M5-1-u6-X15"},{"t":"32 cm","mis":"M5-1-u6-X15"},{"t":"20 cm","mis":"M5-1-u6-X03"}],"explanation":["반으로 자른 직사각형은 가로 8 cm, 세로 4 cm예요.","자른 자리도 새 변이 되어 둘레에 들어가요.","(8 + 4) × 2 = 24 — 둘레는 24 cm예요. 정사각형 둘레 32의 절반이 아니에요."]},{"stem":"한 변이 10 cm인 정사각형 색종이를 똑같은 직사각형 두 개가 되도록 반으로 잘랐어요. 잘라 낸 직사각형 한 개의 둘레는 몇 cm인가요?","options":[{"t":"30 cm","correct":true},{"t":"20 cm","mis":"M5-1-u6-X15"},{"t":"40 cm","mis":"M5-1-u6-X15"},{"t":"25 cm","mis":"M5-1-u6-X03"}],"explanation":["반으로 자른 직사각형은 가로 10 cm, 세로 5 cm예요.","자른 자리도 새 변이 되어 둘레에 들어가요.","(10 + 5) × 2 = 30 — 둘레는 30 cm예요. 정사각형 둘레 40의 절반이 아니에요."]}]}}'::jsonb),
('g5_1_math_u6_L02_challenge#10','math',5,1,'u6','L02','g5_1_math_u6_L02_challenge','lesson_challenge','M5-1-u6-C1',4,'essay','teacher','둘레가 같은 두 직사각형은 넓이도 같을까요? 예를 들어 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u6-C1","difficulty":4,"kind":"essay","stem":"둘레가 같은 두 직사각형은 넓이도 같을까요? 예를 들어 설명하세요.","answer_guide":{"answer":"예: 같지 않을 수 있다. 가로 5 cm, 세로 5 cm인 정사각형과 가로 9 cm, 세로 1 cm인 직사각형은 둘레가 모두 20 cm이지만 넓이는 25 cm²와 9 cm²로 다르다. 둘레는 가장자리의 길이이고 넓이는 덮은 칸의 수라 서로 다른 양이기 때문이다.","scoring_points":["같지 않을 수 있다고 답했는가","둘레가 같고 넓이가 다른 두 직사각형의 예를 바르게 셈했는가","둘레는 길이, 넓이는 칸의 수라 다른 양이라고 설명했는가"]},"explanation":["둘레가 20 cm인 직사각형은 5 × 5, 9 × 1처럼 여러 가지예요.","넓이는 5 × 5 = 25, 9 × 1 = 9로 달라요.","둘레가 같아도 넓이는 다를 수 있어요."]}'::jsonb),
('g5_1_math_u6_L03_basic#1','math',5,1,'u6','L03','g5_1_math_u6_L03_basic','lesson_basic','M5-1-u6-C3',1,'mc','auto','마름모의 둘레를 구하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M5-1-u6-X13','M5-1-u6-X03']::text[],true,'{"seq":1,"concept":"M5-1-u6-C3","difficulty":1,"kind":"mc","stem":"마름모의 둘레를 구하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 변의 길이를 4배 한다","correct":true},{"t":"두 대각선의 길이를 더한다","mis":"M5-1-u6-X13"},{"t":"한 변의 길이를 2배 한다","mis":"M5-1-u6-X03"},{"t":"두 대각선의 길이를 곱한다","mis":"M5-1-u6-X13"}],"explanation":["마름모는 네 변의 길이가 모두 같아요.","같은 길이를 네 번 더하는 것은 4배 하는 것과 같아요.","그래서 마름모의 둘레는 (한 변의 길이) × 4예요."],"variant_rule":{"alt":[{"stem":"정다각형의 둘레를 구하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"(한 변의 길이) × (변의 수)","correct":true},{"t":"(한 변의 길이) × 4","mis":"M5-1-u6-X05"},{"t":"(변의 수) ÷ (한 변의 길이)","mis":"M5-1-u6-X14"},{"t":"(한 변의 길이) + (변의 수)","mis":"M5-1-u6-X16"}],"explanation":["정다각형은 변의 길이가 모두 같아요.","같은 길이를 변의 수만큼 거듭 더하는 것이 곱셈이에요.","그래서 (한 변의 길이) × (변의 수)예요."]},{"stem":"정오각형의 둘레를 구하는 식으로 알맞은 것은 어느 것인가요? (한 변 6 cm)","options":[{"t":"6 × 5","correct":true},{"t":"6 × 4","mis":"M5-1-u6-X05"},{"t":"6 × 6","mis":"M5-1-u6-X05"},{"t":"6 + 5","mis":"M5-1-u6-X16"}],"explanation":["정오각형은 변이 5개이고 길이가 모두 같아요.","6 cm를 5번 더하는 것과 같아요.","그래서 6 × 5 = 30으로 구해요."]}]}}'::jsonb),
('g5_1_math_u6_L03_basic#2','math',5,1,'u6','L03','g5_1_math_u6_L03_basic','lesson_basic','M5-1-u6-C3',1,'sa','auto','한 변의 길이가 7 cm인 마름모 모양 타일이 있어요. 타일의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M5-1-u6-C3","difficulty":1,"kind":"sa","stem":"한 변의 길이가 7 cm인 마름모 모양 타일이 있어요. 타일의 둘레는 몇 cm인가요?","answer":["28"],"explanation":["마름모는 네 변의 길이가 모두 같아요.","7 + 7 + 7 + 7 = 28이에요.","7 × 4 = 28 — 둘레는 28 cm예요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 9 cm인 마름모 모양 타일이 있어요. 타일의 둘레는 몇 cm인가요?","answer":["36"],"explanation":["마름모는 네 변의 길이가 모두 같아요.","9 + 9 + 9 + 9 = 36이에요.","9 × 4 = 36 — 둘레는 36 cm예요."]},{"stem":"한 변의 길이가 12 m인 마름모 모양 화단이 있어요. 화단의 둘레는 몇 m인가요?","answer":["48"],"explanation":["마름모는 네 변의 길이가 모두 같아요.","12 + 12 + 12 + 12 = 48이에요.","12 × 4 = 48 — 둘레는 48 m예요."]}]}}'::jsonb),
('g5_1_math_u6_L03_basic#3','math',5,1,'u6','L03','g5_1_math_u6_L03_basic','lesson_basic','M5-1-u6-C3',1,'mc','auto','한 변의 길이가 4 cm인 정오각형의 둘레는 몇 cm인가요?',ARRAY['M5-1-u6-X05','M5-1-u6-X16']::text[],true,'{"seq":3,"concept":"M5-1-u6-C3","difficulty":1,"kind":"mc","stem":"한 변의 길이가 4 cm인 정오각형의 둘레는 몇 cm인가요?","options":[{"t":"20 cm","correct":true},{"t":"16 cm","mis":"M5-1-u6-X05"},{"t":"24 cm","mis":"M5-1-u6-X05"},{"t":"9 cm","mis":"M5-1-u6-X16"}],"explanation":["정오각형은 변이 5개이고 길이가 모두 같아요.","4 cm를 5번 더하는 것과 같아요.","4 × 5 = 20 — 둘레는 20 cm예요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 5 cm인 정육각형의 둘레는 몇 cm인가요?","options":[{"t":"30 cm","correct":true},{"t":"20 cm","mis":"M5-1-u6-X05"},{"t":"35 cm","mis":"M5-1-u6-X05"},{"t":"25 cm","mis":"M5-1-u6-X05"}],"explanation":["정육각형은 변이 6개이고 길이가 모두 같아요.","5 cm를 6번 더하는 것과 같아요.","5 × 6 = 30 — 둘레는 30 cm예요."]},{"stem":"한 변의 길이가 8 cm인 정삼각형의 둘레는 몇 cm인가요?","options":[{"t":"24 cm","correct":true},{"t":"32 cm","mis":"M5-1-u6-X05"},{"t":"16 cm","mis":"M5-1-u6-X05"},{"t":"11 cm","mis":"M5-1-u6-X16"}],"explanation":["정삼각형은 변이 3개이고 길이가 모두 같아요.","8 cm를 3번 더하는 것과 같아요.","8 × 3 = 24 — 둘레는 24 cm예요."]}]}}'::jsonb),
('g5_1_math_u6_L03_basic#4','math',5,1,'u6','L03','g5_1_math_u6_L03_basic','lesson_basic','M5-1-u6-C3',1,'sa','auto','한 변의 길이가 12 m인 정칠각형의 둘레는 몇 m인가요?','{}'::text[],true,'{"seq":4,"concept":"M5-1-u6-C3","difficulty":1,"kind":"sa","stem":"한 변의 길이가 12 m인 정칠각형의 둘레는 몇 m인가요?","answer":["84"],"explanation":["정칠각형은 변이 7개예요.","변의 길이가 모두 12 m로 같아요.","12 × 7 = 84 — 둘레는 84 m예요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 9 cm인 정팔각형의 둘레는 몇 cm인가요?","answer":["72"],"explanation":["정팔각형은 변이 8개예요.","변의 길이가 모두 9 cm로 같아요.","9 × 8 = 72 — 둘레는 72 cm예요."]},{"stem":"한 변의 길이가 6 cm인 정구각형의 둘레는 몇 cm인가요?","answer":["54"],"explanation":["정구각형은 변이 9개예요.","변의 길이가 모두 6 cm로 같아요.","6 × 9 = 54 — 둘레는 54 cm예요."]}]}}'::jsonb),
('g5_1_math_u6_L03_basic#5','math',5,1,'u6','L03','g5_1_math_u6_L03_basic','lesson_basic','M5-1-u6-C3',2,'sa','auto','둘레가 45 cm인 정구각형의 한 변의 길이는 몇 cm인가요?','{}'::text[],true,'{"seq":5,"concept":"M5-1-u6-C3","difficulty":2,"kind":"sa","stem":"둘레가 45 cm인 정구각형의 한 변의 길이는 몇 cm인가요?","answer":["5"],"explanation":["정구각형의 둘레는 (한 변의 길이) × 9예요.","□ × 9 = 45니 □ = 45 ÷ 9예요.","45 ÷ 9 = 5 — 한 변은 5 cm예요."],"mis":"M5-1-u6-X14","variant_rule":{"alt":[{"stem":"둘레가 42 cm인 정육각형의 한 변의 길이는 몇 cm인가요?","answer":["7"],"explanation":["정육각형의 둘레는 (한 변의 길이) × 6이에요.","□ × 6 = 42니 □ = 42 ÷ 6이에요.","42 ÷ 6 = 7 — 한 변은 7 cm예요."]},{"stem":"둘레가 96 cm인 정팔각형의 한 변의 길이는 몇 cm인가요?","answer":["12"],"explanation":["정팔각형의 둘레는 (한 변의 길이) × 8이에요.","□ × 8 = 96이니 □ = 96 ÷ 8이에요.","96 ÷ 8 = 12 — 한 변은 12 cm예요."]}]}}'::jsonb),
('g5_1_math_u6_L03_basic#6','math',5,1,'u6','L03','g5_1_math_u6_L03_basic','lesson_basic','M5-1-u6-C3',2,'mc','auto','둘레가 가장 짧은 것은 어느 것인가요? ㉠ 한 변 7 cm인 마름모 ㉡ 한 변 5 cm인 정육각형 ㉢ 한 변 3 cm인 정팔각형',ARRAY['M5-1-u6-X05','M5-1-u6-X17','M5-1-u6-X16']::text[],true,'{"seq":6,"concept":"M5-1-u6-C3","difficulty":2,"kind":"mc","stem":"둘레가 가장 짧은 것은 어느 것인가요? ㉠ 한 변 7 cm인 마름모 ㉡ 한 변 5 cm인 정육각형 ㉢ 한 변 3 cm인 정팔각형","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M5-1-u6-X05"},{"t":"㉡","mis":"M5-1-u6-X17"},{"t":"세 둘레가 같다","mis":"M5-1-u6-X16"}],"explanation":["둘레는 (한 변의 길이) × (변의 수)예요.","㉠ 7 × 4 = 28, ㉡ 5 × 6 = 30, ㉢ 3 × 8 = 24예요.","가장 짧은 것은 ㉢이에요."],"variant_rule":{"alt":[{"stem":"둘레가 가장 긴 것은 어느 것인가요? ㉠ 한 변 9 cm인 정삼각형 ㉡ 한 변 6 cm인 정오각형 ㉢ 한 변 8 cm인 정사각형","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M5-1-u6-X17"},{"t":"㉡","mis":"M5-1-u6-X05"},{"t":"세 둘레가 같다","mis":"M5-1-u6-X16"}],"explanation":["둘레는 (한 변의 길이) × (변의 수)예요.","㉠ 9 × 3 = 27, ㉡ 6 × 5 = 30, ㉢ 8 × 4 = 32예요.","가장 긴 것은 ㉢이에요."]},{"stem":"둘레가 가장 짧은 것은 어느 것인가요? ㉠ 한 변 4 cm인 정육각형 ㉡ 한 변 5 cm인 마름모 ㉢ 한 변 3 cm인 정오각형","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M5-1-u6-X17"},{"t":"㉡","mis":"M5-1-u6-X05"},{"t":"세 둘레가 같다","mis":"M5-1-u6-X16"}],"explanation":["둘레는 (한 변의 길이) × (변의 수)예요.","㉠ 4 × 6 = 24, ㉡ 5 × 4 = 20, ㉢ 3 × 5 = 15예요.","가장 짧은 것은 ㉢이에요."]}]}}'::jsonb),
('g5_1_math_u6_L03_basic#7','math',5,1,'u6','L03','g5_1_math_u6_L03_basic','lesson_basic','M5-1-u6-C3',2,'ox','auto','마름모의 둘레는 두 대각선의 길이를 더해서 구해요.',ARRAY['M5-1-u6-X13']::text[],true,'{"seq":7,"concept":"M5-1-u6-C3","difficulty":2,"kind":"ox","stem":"마름모의 둘레는 두 대각선의 길이를 더해서 구해요.","answer":"X","reason_options":[{"t":"마름모의 둘레는 가장자리인 네 변의 길이의 합이므로","correct":true},{"t":"대각선이 마름모를 가로지르는 가장 긴 선이므로","mis":"M5-1-u6-X13"}],"mis":"M5-1-u6-X13","explanation":["둘레는 가장자리를 따라 잰 길이예요.","대각선은 안쪽을 가로지르는 선이라 가장자리가 아니에요.","마름모의 둘레는 (한 변의 길이) × 4예요."],"variant_rule":{"alt":[{"stem":"변의 수가 많은 정다각형일수록 둘레가 반드시 길어요.","answer":"X","reason_options":[{"t":"한 변 3 cm 정팔각형(24 cm)가 한 변 7 cm 마름모(28 cm)보다 짧으므로","correct":true},{"t":"변이 많으면 늘 더 많이 더하므로","mis":"M5-1-u6-X05"}],"explanation":["둘레는 변의 수뿐 아니라 한 변의 길이에도 달려 있어요.","정팔각형 3 × 8 = 24, 마름모 7 × 4 = 28이에요.","변이 더 많은 정팔각형이 오히려 짧아요."]},{"stem":"한 변의 길이와 변의 수만 알면 정다각형의 둘레를 구할 수 있어요.","answer":"O","reason_options":[{"t":"변의 길이가 모두 같아 (한 변) × (변의 수)로 구하므로","correct":true},{"t":"정다각형은 변이 언제나 4개이므로","mis":"M5-1-u6-X05"}],"explanation":["정다각형은 모든 변의 길이가 같아요.","그래서 한 변을 변의 수만큼 거듭 더하면 둘레예요.","(한 변의 길이) × (변의 수)로 구해요."]}]}}'::jsonb),
('g5_1_math_u6_L03_basic#8','math',5,1,'u6','L03','g5_1_math_u6_L03_basic','lesson_basic','M5-1-u6-C3',2,'match','auto','한 변의 길이가 6 cm인 도형과 그 둘레를 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u6-C3","difficulty":2,"kind":"match","stem":"한 변의 길이가 6 cm인 도형과 그 둘레를 알맞게 이으세요.","pairs":[{"l":"정삼각형","r":"18 cm"},{"l":"마름모","r":"24 cm"},{"l":"정육각형","r":"36 cm"}],"mis":"M5-1-u6-X05","explanation":["정삼각형은 변이 3개 — 6 × 3 = 18이에요.","마름모는 변이 4개 — 6 × 4 = 24예요.","정육각형은 변이 6개 — 6 × 6 = 36이에요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 5 cm인 도형과 그 둘레를 알맞게 이으세요.","pairs":[{"l":"정오각형","r":"25 cm"},{"l":"정팔각형","r":"40 cm"},{"l":"정사각형","r":"20 cm"}],"explanation":["정오각형은 변이 5개 — 5 × 5 = 25예요.","정팔각형은 변이 8개 — 5 × 8 = 40이에요.","정사각형은 변이 4개 — 5 × 4 = 20이에요."]}]}}'::jsonb),
('g5_1_math_u6_L03_basic#9','math',5,1,'u6','L03','g5_1_math_u6_L03_basic','lesson_basic','M5-1-u6-C3',2,'mc','auto','길이가 60 cm인 철사를 남김없이 모두 써서 정오각형 하나를 만들었어요. 한 변의 길이는 몇 cm인가요?',ARRAY['M5-1-u6-X05','M5-1-u6-X14']::text[],true,'{"seq":9,"concept":"M5-1-u6-C3","difficulty":2,"kind":"mc","stem":"길이가 60 cm인 철사를 남김없이 모두 써서 정오각형 하나를 만들었어요. 한 변의 길이는 몇 cm인가요?","options":[{"t":"12 cm","correct":true},{"t":"15 cm","mis":"M5-1-u6-X05"},{"t":"10 cm","mis":"M5-1-u6-X05"},{"t":"55 cm","mis":"M5-1-u6-X14"}],"explanation":["철사의 길이가 곧 정오각형의 둘레예요.","정오각형은 변이 5개라 □ × 5 = 60이에요.","60 ÷ 5 = 12 — 한 변은 12 cm예요."],"variant_rule":{"alt":[{"stem":"길이가 54 cm인 철사를 남김없이 모두 써서 정육각형 하나를 만들었어요. 한 변의 길이는 몇 cm인가요?","options":[{"t":"9 cm","correct":true},{"t":"48 cm","mis":"M5-1-u6-X14"},{"t":"324 cm","mis":"M5-1-u6-X14"},{"t":"10 cm","mis":"M5-1-u6-X16"}],"explanation":["철사의 길이가 곧 정육각형의 둘레예요.","정육각형은 변이 6개라 □ × 6 = 54예요.","54 ÷ 6 = 9 — 한 변은 9 cm예요."]},{"stem":"길이가 56 cm인 철사를 남김없이 모두 써서 정팔각형 하나를 만들었어요. 한 변의 길이는 몇 cm인가요?","options":[{"t":"7 cm","correct":true},{"t":"14 cm","mis":"M5-1-u6-X05"},{"t":"8 cm","mis":"M5-1-u6-X05"},{"t":"48 cm","mis":"M5-1-u6-X14"}],"explanation":["철사의 길이가 곧 정팔각형의 둘레예요.","정팔각형은 변이 8개라 □ × 8 = 56이에요.","56 ÷ 8 = 7 — 한 변은 7 cm예요."]}]}}'::jsonb),
('g5_1_math_u6_L03_basic#10','math',5,1,'u6','L03','g5_1_math_u6_L03_basic','lesson_basic','M5-1-u6-C3',3,'sa','auto','한 변이 12 m인 정사각형 태권도 경기장이에요. 가장자리에서 안쪽으로 2 m씩 들어간 정사각형 경기 지역의 둘레는 몇 m인가요?','{}'::text[],true,'{"seq":10,"concept":"M5-1-u6-C3","difficulty":3,"kind":"sa","stem":"한 변이 12 m인 정사각형 태권도 경기장이에요. 가장자리에서 안쪽으로 2 m씩 들어간 정사각형 경기 지역의 둘레는 몇 m인가요?","answer":["32"],"explanation":["양쪽에서 2 m씩 들어가니 한 변은 12 − 2 − 2 = 8이에요.","경기 지역도 정사각형이라 네 변이 같아요.","8 × 4 = 32 — 둘레는 32 m예요."],"variant_rule":{"alt":[{"stem":"한 변이 15 m인 정사각형 태권도 경기장이에요. 가장자리에서 안쪽으로 2 m씩 들어간 정사각형 경기 지역의 둘레는 몇 m인가요?","answer":["44"],"explanation":["양쪽에서 2 m씩 들어가니 한 변은 15 − 2 − 2 = 11이에요.","경기 지역도 정사각형이라 네 변이 같아요.","11 × 4 = 44 — 둘레는 44 m예요."]},{"stem":"한 변이 13 m인 정사각형 태권도 경기장이에요. 가장자리에서 안쪽으로 3 m씩 들어간 정사각형 경기 지역의 둘레는 몇 m인가요?","answer":["28"],"explanation":["양쪽에서 3 m씩 들어가니 한 변은 13 − 3 − 3 = 7이에요.","경기 지역도 정사각형이라 네 변이 같아요.","7 × 4 = 28 — 둘레는 28 m예요."]}]}}'::jsonb),
('g5_1_math_u6_L03_challenge#1','math',5,1,'u6','L03','g5_1_math_u6_L03_challenge','lesson_challenge','M5-1-u6-C3',2,'error','auto','한 변의 길이가 3 cm인 정팔각형의 둘레를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u6-X05','M5-1-u6-X17']::text[],true,'{"seq":1,"concept":"M5-1-u6-C3","difficulty":2,"kind":"error","stem":"한 변의 길이가 3 cm인 정팔각형의 둘레를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「한 변을 4배 한 12 cm야.」","correct":true,"mis_target":"M5-1-u6-X05"},{"t":"도현 — 「변이 8개라 3 × 8로 구해.」","mis":"M5-1-u6-X17"},{"t":"하은 — 「3 cm를 8번 더한 것과 같아.」","mis":"M5-1-u6-X17"}],"explanation":["정팔각형은 변이 8개예요.","4를 곱하는 것은 변이 4개인 마름모·정사각형일 때예요.","서윤은 변의 수를 잘못 써서 틀렸어요 — 둘레는 3 × 8 = 24예요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 5 cm인 정육각형의 둘레를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「한 변을 4배 한 20 cm야.」","correct":true,"mis_target":"M5-1-u6-X05"},{"t":"라온 — 「변이 6개라 5 × 6으로 구해.」","mis":"M5-1-u6-X17"},{"t":"예준 — 「5 cm를 6번 더한 것과 같아.」","mis":"M5-1-u6-X17"}],"explanation":["정육각형은 변이 6개예요.","4를 곱하는 것은 변이 4개인 마름모·정사각형일 때예요.","지민은 변의 수를 잘못 써서 틀렸어요 — 둘레는 5 × 6 = 30이에요."]},{"stem":"한 변의 길이가 7 cm인 정오각형의 둘레를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤아 — 「한 변을 4배 한 28 cm야.」","correct":true,"mis_target":"M5-1-u6-X05"},{"t":"시우 — 「변이 5개라 7 × 5로 구해.」","mis":"M5-1-u6-X17"},{"t":"나린 — 「7 cm를 5번 더한 것과 같아.」","mis":"M5-1-u6-X17"}],"explanation":["정오각형은 변이 5개예요.","4를 곱하는 것은 변이 4개인 마름모·정사각형일 때예요.","윤아는 변의 수를 잘못 써서 틀렸어요 — 둘레는 7 × 5 = 35예요."]}]}}'::jsonb),
('g5_1_math_u6_L03_challenge#2','math',5,1,'u6','L03','g5_1_math_u6_L03_challenge','lesson_challenge','M5-1-u6-C3',2,'sa','auto','한 변이 8 cm인 정삼각형과 둘레가 같은 정사각형이 있어요. 정사각형의 한 변의 길이는 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M5-1-u6-C3","difficulty":2,"kind":"sa","stem":"한 변이 8 cm인 정삼각형과 둘레가 같은 정사각형이 있어요. 정사각형의 한 변의 길이는 몇 cm인가요?","answer":["6"],"explanation":["정삼각형의 둘레는 8 × 3 = 24예요.","정사각형의 둘레도 24 cm니 □ × 4 = 24예요.","24 ÷ 4 = 6 — 한 변은 6 cm예요."],"mis":"M5-1-u6-X14","variant_rule":{"alt":[{"stem":"한 변이 4 cm인 정오각형과 둘레가 같은 정사각형이 있어요. 정사각형의 한 변의 길이는 몇 cm인가요?","answer":["5"],"explanation":["정오각형의 둘레는 4 × 5 = 20이에요.","정사각형의 둘레도 20 cm니 □ × 4 = 20이에요.","20 ÷ 4 = 5 — 한 변은 5 cm예요."]},{"stem":"한 변이 4 cm인 정육각형과 둘레가 같은 정팔각형이 있어요. 정팔각형의 한 변의 길이는 몇 cm인가요?","answer":["3"],"explanation":["정육각형의 둘레는 4 × 6 = 24예요.","정팔각형의 둘레도 24 cm니 □ × 8 = 24예요.","24 ÷ 8 = 3 — 한 변은 3 cm예요."]}]}}'::jsonb),
('g5_1_math_u6_L03_challenge#3','math',5,1,'u6','L03','g5_1_math_u6_L03_challenge','lesson_challenge','M5-1-u6-C3',3,'mc','auto','둘레에 대한 설명으로 옳은 것은 어느 것인가요?',ARRAY['M5-1-u6-X05','M5-1-u6-X13']::text[],true,'{"seq":3,"concept":"M5-1-u6-C3","difficulty":3,"kind":"mc","stem":"둘레에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"정다각형은 한 변의 길이와 변의 수만 알면 둘레를 구할 수 있다","correct":true},{"t":"정다각형의 둘레는 언제나 한 변의 4배다","mis":"M5-1-u6-X05"},{"t":"마름모의 둘레는 대각선의 길이로 구한다","mis":"M5-1-u6-X13"},{"t":"변의 수가 많을수록 둘레가 반드시 길다","mis":"M5-1-u6-X05"}],"explanation":["정다각형은 변의 길이가 모두 같아요.","그래서 (한 변) × (변의 수)면 둘레예요.","4배는 변이 4개일 때만, 대각선은 둘레와 상관없어요."],"variant_rule":{"alt":[{"stem":"둘레에 대한 설명으로 옳지 않은 것은 어느 것인가요?","options":[{"t":"정육각형의 둘레는 한 변의 길이를 4배 하여 구한다","correct":true},{"t":"마름모의 둘레는 한 변의 길이를 4배 하여 구한다","mis":"M5-1-u6-X17"},{"t":"정삼각형의 둘레는 한 변의 길이를 3배 하여 구한다","mis":"M5-1-u6-X17"},{"t":"정팔각형의 둘레는 한 변의 길이를 8배 하여 구한다","mis":"M5-1-u6-X17"}],"explanation":["정육각형은 변이 6개예요.","그래서 한 변을 6배 해야 둘레예요.","옳지 않은 것은 「정육각형 … 4배」예요."]},{"stem":"한 변의 길이가 같은 마름모와 정사각형의 둘레를 견주면 어떠한가요?","options":[{"t":"두 둘레가 같다","correct":true},{"t":"마름모의 둘레가 더 길다","mis":"M5-1-u6-X13"},{"t":"정사각형의 둘레가 더 길다","mis":"M5-1-u6-X13"},{"t":"알 수 없다","mis":"M5-1-u6-X13"}],"explanation":["마름모도 정사각형도 네 변의 길이가 모두 같아요.","둘 다 (한 변) × 4예요.","한 변이 같으면 둘레도 같아요 — 모양이 달라도요."]}]}}'::jsonb),
('g5_1_math_u6_L03_challenge#4','math',5,1,'u6','L03','g5_1_math_u6_L03_challenge','lesson_challenge','M5-1-u6-C3',3,'sa','auto','한 변이 9 cm인 정사각형과 둘레가 같은 정육각형이 있어요. 정육각형의 한 변의 길이는 몇 cm인가요?','{}'::text[],true,'{"seq":4,"concept":"M5-1-u6-C3","difficulty":3,"kind":"sa","stem":"한 변이 9 cm인 정사각형과 둘레가 같은 정육각형이 있어요. 정육각형의 한 변의 길이는 몇 cm인가요?","answer":["6"],"explanation":["정사각형의 둘레는 9 × 4 = 36이에요.","정육각형의 둘레도 36 cm니 □ × 6 = 36이에요.","36 ÷ 6 = 6 — 한 변은 6 cm예요."],"mis":"M5-1-u6-X14","variant_rule":{"alt":[{"stem":"한 변이 6 cm인 정오각형과 둘레가 같은 정삼각형이 있어요. 정삼각형의 한 변의 길이는 몇 cm인가요?","answer":["10"],"explanation":["정오각형의 둘레는 6 × 5 = 30이에요.","정삼각형의 둘레도 30 cm니 □ × 3 = 30이에요.","30 ÷ 3 = 10 — 한 변은 10 cm예요."]},{"stem":"한 변이 3 cm인 정팔각형과 둘레가 같은 정사각형이 있어요. 정사각형의 한 변의 길이는 몇 cm인가요?","answer":["6"],"explanation":["정팔각형의 둘레는 3 × 8 = 24예요.","정사각형의 둘레도 24 cm니 □ × 4 = 24예요.","24 ÷ 4 = 6 — 한 변은 6 cm예요."]}]}}'::jsonb),
('g5_1_math_u6_L03_challenge#5','math',5,1,'u6','L03','g5_1_math_u6_L03_challenge','lesson_challenge','M5-1-u6-C3',3,'sa','auto','한 변이 5 cm인 정삼각형 4개를 겹치지 않게 변끼리 맞붙여 한 줄로 이었어요. 만든 도형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":5,"concept":"M5-1-u6-C3","difficulty":3,"kind":"sa","stem":"한 변이 5 cm인 정삼각형 4개를 겹치지 않게 변끼리 맞붙여 한 줄로 이었어요. 만든 도형의 둘레는 몇 cm인가요?","answer":["30"],"explanation":["정삼각형 4개의 변은 모두 3 × 4 = 12개예요.","맞붙은 곳 3군데에서 변이 2개씩 안쪽으로 들어가 가장자리 변은 12 − 6 = 6개예요.","5 × 6 = 30 — 둘레는 30 cm예요."],"mis":"M5-1-u6-X15","variant_rule":{"alt":[{"stem":"한 변이 7 cm인 정삼각형 3개를 겹치지 않게 변끼리 맞붙여 한 줄로 이었어요. 만든 도형의 둘레는 몇 cm인가요?","answer":["35"],"explanation":["정삼각형 3개의 변은 모두 3 × 3 = 9개예요.","맞붙은 곳 2군데에서 변이 2개씩 안쪽으로 들어가 가장자리 변은 9 − 4 = 5개예요.","7 × 5 = 35 — 둘레는 35 cm예요."]},{"stem":"한 변이 9 cm인 정삼각형 2개를 겹치지 않게 변끼리 맞붙여 한 줄로 이었어요. 만든 도형의 둘레는 몇 cm인가요?","answer":["36"],"explanation":["정삼각형 2개의 변은 모두 3 × 2 = 6개예요.","맞붙은 곳 1군데에서 변이 2개씩 안쪽으로 들어가 가장자리 변은 6 − 2 = 4개예요.","9 × 4 = 36 — 둘레는 36 cm예요."]}]}}'::jsonb),
('g5_1_math_u6_L03_challenge#6','math',5,1,'u6','L03','g5_1_math_u6_L03_challenge','lesson_challenge','M5-1-u6-C3',3,'sa','auto','한 변의 길이가 8 cm로 같은 정오각형과 정사각형이 있어요. 두 도형의 둘레의 차는 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M5-1-u6-C3","difficulty":3,"kind":"sa","stem":"한 변의 길이가 8 cm로 같은 정오각형과 정사각형이 있어요. 두 도형의 둘레의 차는 몇 cm인가요?","answer":["8"],"explanation":["정오각형의 둘레는 8 × 5 = 40이에요.","정사각형의 둘레는 8 × 4 = 32예요.","40 − 32 = 8 — 차는 8 cm예요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 7 cm로 같은 정육각형과 정삼각형이 있어요. 두 도형의 둘레의 차는 몇 cm인가요?","answer":["21"],"explanation":["정육각형의 둘레는 7 × 6 = 42예요.","정삼각형의 둘레는 7 × 3 = 21이에요.","42 − 21 = 21 — 차는 21 cm예요."]},{"stem":"한 변의 길이가 9 cm로 같은 정팔각형과 정육각형이 있어요. 두 도형의 둘레의 차는 몇 cm인가요?","answer":["18"],"explanation":["정팔각형의 둘레는 9 × 8 = 72예요.","정육각형의 둘레는 9 × 6 = 54예요.","72 − 54 = 18 — 차는 18 cm예요."]}]}}'::jsonb),
('g5_1_math_u6_L03_challenge#7','math',5,1,'u6','L03','g5_1_math_u6_L03_challenge','lesson_challenge','M5-1-u6-C3',3,'sa','auto','한 변이 14 m인 정사각형 태권도 경기장이에요. 가장자리에서 안쪽으로 3 m씩 들어간 정사각형 경기 지역의 둘레는 몇 m인가요?','{}'::text[],true,'{"seq":7,"concept":"M5-1-u6-C3","difficulty":3,"kind":"sa","stem":"한 변이 14 m인 정사각형 태권도 경기장이에요. 가장자리에서 안쪽으로 3 m씩 들어간 정사각형 경기 지역의 둘레는 몇 m인가요?","answer":["32"],"explanation":["양쪽에서 3 m씩 들어가니 한 변은 14 − 3 − 3 = 8이에요.","경기 지역도 정사각형이라 네 변이 같아요.","8 × 4 = 32 — 둘레는 32 m예요."],"variant_rule":{"alt":[{"stem":"한 변이 16 m인 정사각형 태권도 경기장이에요. 가장자리에서 안쪽으로 2 m씩 들어간 정사각형 경기 지역의 둘레는 몇 m인가요?","answer":["48"],"explanation":["양쪽에서 2 m씩 들어가니 한 변은 16 − 2 − 2 = 12예요.","경기 지역도 정사각형이라 네 변이 같아요.","12 × 4 = 48 — 둘레는 48 m예요."]},{"stem":"한 변이 11 m인 정사각형 태권도 경기장이에요. 가장자리에서 안쪽으로 1 m씩 들어간 정사각형 경기 지역의 둘레는 몇 m인가요?","answer":["36"],"explanation":["양쪽에서 1 m씩 들어가니 한 변은 11 − 1 − 1 = 9예요.","경기 지역도 정사각형이라 네 변이 같아요.","9 × 4 = 36 — 둘레는 36 m예요."]}]}}'::jsonb),
('g5_1_math_u6_L03_challenge#8','math',5,1,'u6','L03','g5_1_math_u6_L03_challenge','lesson_challenge','M5-1-u6-C3',4,'sa','auto','길이가 100 cm인 철사로 한 변이 7 cm인 정육각형 하나를 만들었어요. 남은 철사는 몇 cm인가요?','{}'::text[],true,'{"seq":8,"concept":"M5-1-u6-C3","difficulty":4,"kind":"sa","stem":"길이가 100 cm인 철사로 한 변이 7 cm인 정육각형 하나를 만들었어요. 남은 철사는 몇 cm인가요?","answer":["58"],"explanation":["정육각형을 만드는 데 쓴 철사는 둘레만큼이에요.","7 × 6 = 42예요.","100 − 42 = 58 — 남은 철사는 58 cm예요."],"variant_rule":{"alt":[{"stem":"길이가 100 cm인 철사로 한 변이 9 cm인 정팔각형 하나를 만들었어요. 남은 철사는 몇 cm인가요?","answer":["28"],"explanation":["정팔각형을 만드는 데 쓴 철사는 둘레만큼이에요.","9 × 8 = 72예요.","100 − 72 = 28 — 남은 철사는 28 cm예요."]},{"stem":"길이가 90 cm인 철사로 한 변이 13 cm인 정오각형 하나를 만들었어요. 남은 철사는 몇 cm인가요?","answer":["25"],"explanation":["정오각형을 만드는 데 쓴 철사는 둘레만큼이에요.","13 × 5 = 65예요.","90 − 65 = 25 — 남은 철사는 25 cm예요."]}]}}'::jsonb),
('g5_1_math_u6_L03_challenge#9','math',5,1,'u6','L03','g5_1_math_u6_L03_challenge','lesson_challenge','M5-1-u6-C3',4,'mc','auto','둘레가 72 cm이고 한 변의 길이가 8 cm인 정다각형이 있어요. 이 정다각형의 이름은 무엇인가요?',ARRAY['M5-1-u6-X05','M5-1-u6-X14']::text[],true,'{"seq":9,"concept":"M5-1-u6-C3","difficulty":4,"kind":"mc","stem":"둘레가 72 cm이고 한 변의 길이가 8 cm인 정다각형이 있어요. 이 정다각형의 이름은 무엇인가요?","options":[{"t":"정구각형","correct":true},{"t":"정팔각형","mis":"M5-1-u6-X05"},{"t":"정십각형","mis":"M5-1-u6-X05"},{"t":"정십일각형","mis":"M5-1-u6-X14"}],"explanation":["정다각형의 둘레는 (한 변의 길이) × (변의 수)예요.","8 × □ = 72니 □ = 72 ÷ 8 = 9예요.","변이 9개인 정다각형은 정구각형이에요."],"variant_rule":{"alt":[{"stem":"둘레가 60 cm이고 한 변의 길이가 12 cm인 정다각형이 있어요. 이 정다각형의 이름은 무엇인가요?","options":[{"t":"정오각형","correct":true},{"t":"정사각형","mis":"M5-1-u6-X05"},{"t":"정육각형","mis":"M5-1-u6-X05"},{"t":"정칠각형","mis":"M5-1-u6-X14"}],"explanation":["정다각형의 둘레는 (한 변의 길이) × (변의 수)예요.","12 × □ = 60이니 □ = 60 ÷ 12 = 5예요.","변이 5개인 정다각형은 정오각형이에요."]},{"stem":"둘레가 84 cm이고 한 변의 길이가 12 cm인 정다각형이 있어요. 이 정다각형의 이름은 무엇인가요?","options":[{"t":"정칠각형","correct":true},{"t":"정육각형","mis":"M5-1-u6-X05"},{"t":"정팔각형","mis":"M5-1-u6-X05"},{"t":"정구각형","mis":"M5-1-u6-X14"}],"explanation":["정다각형의 둘레는 (한 변의 길이) × (변의 수)예요.","12 × □ = 84니 □ = 84 ÷ 12 = 7이에요.","변이 7개인 정다각형은 정칠각형이에요."]}]}}'::jsonb),
('g5_1_math_u6_L03_challenge#10','math',5,1,'u6','L03','g5_1_math_u6_L03_challenge','lesson_challenge','M5-1-u6-C3',4,'essay','teacher','정다각형의 둘레를 (한 변의 길이) × (변의 수)로 구할 수 있는 까닭을 설명하고, 한 변이 4 cm인 정육각형의 둘레를 구하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u6-C3","difficulty":4,"kind":"essay","stem":"정다각형의 둘레를 (한 변의 길이) × (변의 수)로 구할 수 있는 까닭을 설명하고, 한 변이 4 cm인 정육각형의 둘레를 구하세요.","answer_guide":{"answer":"예: 정다각형은 모든 변의 길이가 같으므로 한 변의 길이를 변의 수만큼 거듭 더하면 둘레가 되고, 같은 수를 거듭 더하는 것은 곱셈이다. 정육각형은 변이 6개이므로 4 × 6 = 24, 둘레는 24 cm이다.","scoring_points":["모든 변의 길이가 같다고 썼는가","거듭 더하기가 곱셈이라고 설명했는가","정육각형의 둘레 24 cm를 바르게 구했는가"]},"explanation":["정다각형은 변의 길이가 모두 같아요.","같은 길이를 변의 수만큼 더하는 것이 곱셈이에요.","정육각형: 4 × 6 = 24 — 둘레는 24 cm예요."]}'::jsonb),
('g5_1_math_u6_L05_basic#1','math',5,1,'u6','L05','g5_1_math_u6_L05_basic','lesson_basic','M5-1-u6-C4',1,'mc','auto','1 cm²는 어떤 넓이인가요?',ARRAY['M5-1-u6-X06']::text[],true,'{"seq":1,"concept":"M5-1-u6-C4","difficulty":1,"kind":"mc","stem":"1 cm²는 어떤 넓이인가요?","options":[{"t":"한 변의 길이가 1 cm인 정사각형의 넓이","correct":true},{"t":"둘레가 1 cm인 도형의 넓이","mis":"M5-1-u6-X06"},{"t":"가로가 1 cm인 직사각형의 넓이","mis":"M5-1-u6-X06"},{"t":"네 변의 길이의 합이 4 cm인 아무 도형의 넓이","mis":"M5-1-u6-X06"}],"explanation":["넓이를 견주려면 모두가 같은 크기의 칸을 써야 해요.","그래서 한 변이 1 cm인 정사각형 한 칸의 넓이를 1 cm²로 약속했어요.","둘레나 가로 하나만으로는 칸의 크기가 정해지지 않아요."],"variant_rule":{"alt":[{"stem":"1 cm²를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"1 제곱센티미터","correct":true},{"t":"1 센티미터","mis":"M5-1-u6-X01"},{"t":"1 센티미터 이","mis":"M5-1-u6-X06"},{"t":"1 사각센티미터","mis":"M5-1-u6-X06"}],"explanation":["cm² 오른쪽 위의 작은 2는 제곱이라고 읽어요.","1 cm²는 1 제곱센티미터라고 읽어요.","1 센티미터는 길이의 단위예요."]},{"stem":"넓이를 1 cm² 같은 표준 단위로 재는 까닭은 무엇인가요?","options":[{"t":"같은 크기의 칸으로 세어야 넓이를 비교할 수 있어서","correct":true},{"t":"칸의 수가 적어져서","mis":"M5-1-u6-X06"},{"t":"둘레를 쉽게 구할 수 있어서","mis":"M5-1-u6-X01"},{"t":"도형의 모양을 알 수 있어서","mis":"M5-1-u6-X06"}],"explanation":["친구는 큰 칸, 나는 작은 칸으로 세면 칸의 수를 견주어도 넓이를 견준 게 아니에요.","모두가 같은 칸을 써야 칸의 수로 넓이를 비교할 수 있어요.","그래서 한 변 1 cm 정사각형을 1 cm²로 약속했어요."]}]}}'::jsonb),
('g5_1_math_u6_L05_basic#2','math',5,1,'u6','L05','g5_1_math_u6_L05_basic','lesson_basic','M5-1-u6-C4',1,'sa','auto','도형을 1 cm² 칸으로 빈틈없이 덮었더니 한 줄에 4칸씩 3줄이었어요. 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":2,"concept":"M5-1-u6-C4","difficulty":1,"kind":"sa","stem":"도형을 1 cm² 칸으로 빈틈없이 덮었더니 한 줄에 4칸씩 3줄이었어요. 넓이는 몇 cm²인가요?","answer":["12"],"explanation":["한 줄에 4칸, 그런 줄이 3줄이에요.","4 × 3 = 12 — 칸은 모두 12개예요.","한 칸이 1 cm²니 넓이는 12 cm²예요."],"variant_rule":{"alt":[{"stem":"도형을 1 cm² 칸으로 빈틈없이 덮었더니 한 줄에 5칸씩 3줄이었어요. 넓이는 몇 cm²인가요?","answer":["15"],"explanation":["한 줄에 5칸, 그런 줄이 3줄이에요.","5 × 3 = 15 — 칸은 모두 15개예요.","한 칸이 1 cm²니 넓이는 15 cm²예요."]},{"stem":"도형을 1 cm² 칸으로 빈틈없이 덮었더니 한 줄에 6칸씩 4줄이었어요. 넓이는 몇 cm²인가요?","answer":["24"],"explanation":["한 줄에 6칸, 그런 줄이 4줄이에요.","6 × 4 = 24 — 칸은 모두 24개예요.","한 칸이 1 cm²니 넓이는 24 cm²예요."]}]}}'::jsonb),
('g5_1_math_u6_L05_basic#3','math',5,1,'u6','L05','g5_1_math_u6_L05_basic','lesson_basic','M5-1-u6-C5',1,'mc','auto','직사각형의 넓이를 구하는 식은 어느 것인가요?',ARRAY['M5-1-u6-X01','M5-1-u6-X10']::text[],true,'{"seq":3,"concept":"M5-1-u6-C5","difficulty":1,"kind":"mc","stem":"직사각형의 넓이를 구하는 식은 어느 것인가요?","options":[{"t":"(가로) × (세로)","correct":true},{"t":"(가로 + 세로) × 2","mis":"M5-1-u6-X01"},{"t":"(가로) + (세로)","mis":"M5-1-u6-X01"},{"t":"(가로) × (세로) ÷ 2","mis":"M5-1-u6-X10"}],"explanation":["한 줄에 가로만큼 칸이 있어요.","그런 줄이 세로만큼 있어요.","그래서 직사각형의 넓이는 (가로) × (세로)예요."],"variant_rule":{"alt":[{"stem":"정사각형의 넓이를 구하는 식은 어느 것인가요?","options":[{"t":"(한 변) × (한 변)","correct":true},{"t":"(한 변) × 4","mis":"M5-1-u6-X01"},{"t":"(한 변) × 2","mis":"M5-1-u6-X07"},{"t":"(한 변) + (한 변)","mis":"M5-1-u6-X01"}],"explanation":["정사각형은 가로와 세로가 같은 직사각형이에요.","(가로) × (세로)에서 가로와 세로가 모두 한 변이에요.","그래서 (한 변) × (한 변)이에요 — (한 변) × 4는 둘레예요."]},{"stem":"넓이를 구하는 식으로 잘못된 것은 어느 것인가요?","options":[{"t":"직사각형: (가로 + 세로) × 2","correct":true},{"t":"직사각형: (가로) × (세로)","mis":"M5-1-u6-X17"},{"t":"정사각형: (한 변) × (한 변)","mis":"M5-1-u6-X17"},{"t":"직사각형: (세로) × (가로)","mis":"M5-1-u6-X17"}],"explanation":["(가로 + 세로) × 2는 가장자리 길이, 곧 둘레의 식이에요.","넓이는 칸의 수라 곱해서 구해요.","곱하는 차례를 바꾼 (세로) × (가로)도 같은 넓이예요."]}]}}'::jsonb),
('g5_1_math_u6_L05_basic#4','math',5,1,'u6','L05','g5_1_math_u6_L05_basic','lesson_basic','M5-1-u6-C5',1,'sa','auto','가로 8 cm, 세로 5 cm인 직사각형 카드의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":4,"concept":"M5-1-u6-C5","difficulty":1,"kind":"sa","stem":"가로 8 cm, 세로 5 cm인 직사각형 카드의 넓이는 몇 cm²인가요?","answer":["40"],"explanation":["한 줄에 8칸씩 5줄이라고 생각해요.","넓이는 (가로) × (세로)예요.","8 × 5 = 40 — 넓이는 40 cm²예요."],"variant_rule":{"alt":[{"stem":"가로 9 cm, 세로 6 cm인 직사각형 카드의 넓이는 몇 cm²인가요?","answer":["54"],"explanation":["한 줄에 9칸씩 6줄이라고 생각해요.","넓이는 (가로) × (세로)예요.","9 × 6 = 54 — 넓이는 54 cm²예요."]},{"stem":"가로 12 m, 세로 4 m인 직사각형 꽃밭의 넓이는 몇 m²인가요?","answer":["48"],"explanation":["한 줄에 12칸씩 4줄이라고 생각해요.","넓이는 (가로) × (세로)예요.","12 × 4 = 48 — 넓이는 48 m²예요."]}]}}'::jsonb),
('g5_1_math_u6_L05_basic#5','math',5,1,'u6','L05','g5_1_math_u6_L05_basic','lesson_basic','M5-1-u6-C4',2,'sa','auto','모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":5,"concept":"M5-1-u6-C4","difficulty":2,"kind":"sa","stem":"모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?","answer":["14"],"explanation":["도형을 직사각형 몇 개로 나누어 칸을 세어 봐요.","나눈 부분의 칸을 빠짐없이 모두 더하면 14칸이에요.","한 칸이 1 cm²니 넓이는 14 cm²예요."],"asset":{"type":"geo","items":[{"w":105,"h":105,"grid":15,"poly":[[[15,15],[75,15],[75,45],[45,45],[45,90],[15,90]]],"show":[]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?","answer":["18"],"explanation":["도형을 직사각형 몇 개로 나누어 칸을 세어 봐요.","나눈 부분의 칸을 빠짐없이 모두 더하면 18칸이에요.","한 칸이 1 cm²니 넓이는 18 cm²예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"grid":15,"poly":[[[15,15],[105,15],[105,45],[60,45],[60,75],[15,75]]],"show":[]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?","answer":["14"],"explanation":["도형을 직사각형 몇 개로 나누어 칸을 세어 봐요.","나눈 부분의 칸을 빠짐없이 모두 더하면 14칸이에요.","한 칸이 1 cm²니 넓이는 14 cm²예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[15,15],[45,15],[45,45],[90,45],[90,75],[15,75]]],"show":[]}],"tag":false}}]}}'::jsonb),
('g5_1_math_u6_L05_basic#6','math',5,1,'u6','L05','g5_1_math_u6_L05_basic','lesson_basic','M5-1-u6-C5',2,'mc','auto','한 변의 길이가 6 cm인 정사각형의 넓이는 몇 cm²인가요?',ARRAY['M5-1-u6-X01','M5-1-u6-X07','M5-1-u6-X16']::text[],true,'{"seq":6,"concept":"M5-1-u6-C5","difficulty":2,"kind":"mc","stem":"한 변의 길이가 6 cm인 정사각형의 넓이는 몇 cm²인가요?","options":[{"t":"36 cm²","correct":true},{"t":"24 cm²","mis":"M5-1-u6-X01"},{"t":"12 cm²","mis":"M5-1-u6-X07"},{"t":"30 cm²","mis":"M5-1-u6-X16"}],"explanation":["정사각형은 가로와 세로가 같아요.","넓이는 (한 변) × (한 변)이에요.","6 × 6 = 36 — 넓이는 36 cm²예요. 6 × 4 = 24는 둘레예요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 9 cm인 정사각형의 넓이는 몇 cm²인가요?","options":[{"t":"81 cm²","correct":true},{"t":"36 cm²","mis":"M5-1-u6-X01"},{"t":"18 cm²","mis":"M5-1-u6-X07"},{"t":"45 cm²","mis":"M5-1-u6-X16"}],"explanation":["정사각형은 가로와 세로가 같아요.","넓이는 (한 변) × (한 변)이에요.","9 × 9 = 81 — 넓이는 81 cm²예요. 9 × 4 = 36은 둘레예요."]},{"stem":"한 변의 길이가 7 cm인 정사각형의 넓이는 몇 cm²인가요?","options":[{"t":"49 cm²","correct":true},{"t":"28 cm²","mis":"M5-1-u6-X01"},{"t":"14 cm²","mis":"M5-1-u6-X07"},{"t":"35 cm²","mis":"M5-1-u6-X16"}],"explanation":["정사각형은 가로와 세로가 같아요.","넓이는 (한 변) × (한 변)이에요.","7 × 7 = 49 — 넓이는 49 cm²예요. 7 × 4 = 28은 둘레예요."]}]}}'::jsonb),
('g5_1_math_u6_L05_basic#7','math',5,1,'u6','L05','g5_1_math_u6_L05_basic','lesson_basic','M5-1-u6-C5',2,'sa','auto','넓이가 48 cm²인 직사각형의 가로가 8 cm예요. 세로는 몇 cm인가요?','{}'::text[],true,'{"seq":7,"concept":"M5-1-u6-C5","difficulty":2,"kind":"sa","stem":"넓이가 48 cm²인 직사각형의 가로가 8 cm예요. 세로는 몇 cm인가요?","answer":["6"],"explanation":["(가로) × (세로) = (넓이)예요.","8 × □ = 48이니 □ = 48 ÷ 8이에요.","48 ÷ 8 = 6 — 세로는 6 cm예요."],"mis":"M5-1-u6-X14","variant_rule":{"alt":[{"stem":"넓이가 63 cm²인 직사각형의 가로가 9 cm예요. 세로는 몇 cm인가요?","answer":["7"],"explanation":["(가로) × (세로) = (넓이)예요.","9 × □ = 63이니 □ = 63 ÷ 9예요.","63 ÷ 9 = 7 — 세로는 7 cm예요."]},{"stem":"넓이가 72 cm²인 직사각형의 가로가 8 cm예요. 세로는 몇 cm인가요?","answer":["9"],"explanation":["(가로) × (세로) = (넓이)예요.","8 × □ = 72니 □ = 72 ÷ 8이에요.","72 ÷ 8 = 9 — 세로는 9 cm예요."]}]}}'::jsonb),
('g5_1_math_u6_L05_basic#8','math',5,1,'u6','L05','g5_1_math_u6_L05_basic','lesson_basic','M5-1-u6-C5',2,'mc','auto','넓이가 더 넓은 것은 어느 것인가요? ㉠ 가로 12 cm, 세로 5 cm인 직사각형 ㉡ 한 변이 8 cm인 정사각형',ARRAY['M5-1-u6-X16','M5-1-u6-X02','M5-1-u6-X06']::text[],true,'{"seq":8,"concept":"M5-1-u6-C5","difficulty":2,"kind":"mc","stem":"넓이가 더 넓은 것은 어느 것인가요? ㉠ 가로 12 cm, 세로 5 cm인 직사각형 ㉡ 한 변이 8 cm인 정사각형","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M5-1-u6-X16"},{"t":"두 넓이가 같다","mis":"M5-1-u6-X02"},{"t":"알 수 없다","mis":"M5-1-u6-X06"}],"explanation":["㉠의 넓이는 12 × 5 = 60이에요.","㉡의 넓이는 8 × 8 = 64예요.","㉡의 넓이가 더 넓어요."],"variant_rule":{"alt":[{"stem":"넓이가 더 넓은 것은 어느 것인가요? ㉠ 가로 9 cm, 세로 4 cm인 직사각형 ㉡ 한 변이 7 cm인 정사각형","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M5-1-u6-X16"},{"t":"두 넓이가 같다","mis":"M5-1-u6-X02"},{"t":"알 수 없다","mis":"M5-1-u6-X06"}],"explanation":["㉠의 넓이는 9 × 4 = 36이에요.","㉡의 넓이는 7 × 7 = 49예요.","㉡의 넓이가 더 넓어요."]},{"stem":"넓이가 더 넓은 것은 어느 것인가요? ㉠ 가로 10 cm, 세로 7 cm인 직사각형 ㉡ 한 변이 8 cm인 정사각형","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"M5-1-u6-X16"},{"t":"두 넓이가 같다","mis":"M5-1-u6-X02"},{"t":"알 수 없다","mis":"M5-1-u6-X06"}],"explanation":["㉠의 넓이는 10 × 7 = 70이에요.","㉡의 넓이는 8 × 8 = 64예요.","㉠의 넓이가 더 넓어요."]}]}}'::jsonb),
('g5_1_math_u6_L05_basic#9','math',5,1,'u6','L05','g5_1_math_u6_L05_basic','lesson_basic','M5-1-u6-C5',2,'ox','auto','직사각형의 넓이는 (가로 + 세로) × 2로 구해요.',ARRAY['M5-1-u6-X01']::text[],true,'{"seq":9,"concept":"M5-1-u6-C5","difficulty":2,"kind":"ox","stem":"직사각형의 넓이는 (가로 + 세로) × 2로 구해요.","answer":"X","reason_options":[{"t":"(가로 + 세로) × 2는 둘레의 식이고 넓이는 (가로) × (세로)이므로","correct":true},{"t":"가로와 세로를 모두 쓰는 식이므로","mis":"M5-1-u6-X01"}],"mis":"M5-1-u6-X01","explanation":["둘레는 가장자리의 길이라 더해서 구해요.","넓이는 칸의 수라 한 줄의 칸 수 × 줄의 수로 곱해요.","그래서 넓이는 (가로) × (세로)예요."],"variant_rule":{"alt":[{"stem":"정사각형의 넓이는 한 변의 길이의 2배예요.","answer":"X","reason_options":[{"t":"넓이는 (한 변) × (한 변)이라 한 변 6 cm면 36 cm²이므로","correct":true},{"t":"정사각형은 가로와 세로 두 변이 있으므로","mis":"M5-1-u6-X07"}],"explanation":["정사각형의 넓이는 (한 변) × (한 변)이에요.","한 변이 6 cm면 6 × 6 = 36이에요.","6 × 2 = 12는 넓이가 아니에요."]},{"stem":"가로와 세로를 바꾸어 곱해도 직사각형의 넓이는 같아요.","answer":"O","reason_options":[{"t":"한 줄 칸 수와 줄 수를 바꾸어 세어도 칸의 수는 그대로이므로","correct":true},{"t":"가로와 세로는 늘 같은 길이이므로","mis":"M5-1-u6-X01"}],"explanation":["가로 8 cm, 세로 5 cm면 8칸씩 5줄이에요.","돌려 보면 5칸씩 8줄이에요.","8 × 5 = 40, 5 × 8 = 40 — 넓이는 같아요."]}]}}'::jsonb),
('g5_1_math_u6_L05_basic#10','math',5,1,'u6','L05','g5_1_math_u6_L05_basic','lesson_basic','M5-1-u6-C4',3,'mc','auto','모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 두 직사각형 ㉮, ㉯에 대한 설명으로 옳은 것은 어느 것인가요?',ARRAY['M5-1-u6-X02','M5-1-u6-X16']::text[],true,'{"seq":10,"concept":"M5-1-u6-C4","difficulty":3,"kind":"mc","stem":"모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 두 직사각형 ㉮, ㉯에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"㉮는 둘레가 더 길지만 넓이는 더 좁다","correct":true},{"t":"㉮가 둘레도 넓이도 더 크다","mis":"M5-1-u6-X02"},{"t":"㉯가 둘레도 넓이도 더 크다","mis":"M5-1-u6-X02"},{"t":"두 도형은 넓이가 같다","mis":"M5-1-u6-X16"}],"explanation":["㉮는 둘레 (9 + 1) × 2 = 20, 넓이 9 × 1 = 9예요.","㉯는 둘레 (5 + 3) × 2 = 16, 넓이 5 × 3 = 15예요.","둘레가 긴 ㉮가 오히려 좁아요 — 둘레와 넓이는 다른 양이에요."],"asset":{"type":"geo","items":[{"w":165,"h":75,"grid":15,"poly":[[[15,15],[150,15],[150,30],[15,30]]],"show":[]},{"w":165,"h":75,"grid":15,"poly":[[[15,15],[90,15],[90,60],[15,60]]],"show":[]}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 두 직사각형 ㉮, ㉯에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"㉮는 둘레가 더 길지만 넓이는 더 좁다","correct":true},{"t":"㉮가 둘레도 넓이도 더 크다","mis":"M5-1-u6-X02"},{"t":"㉯가 둘레도 넓이도 더 크다","mis":"M5-1-u6-X02"},{"t":"두 도형은 넓이가 같다","mis":"M5-1-u6-X16"}],"explanation":["㉮는 둘레 (8 + 1) × 2 = 18, 넓이 8 × 1 = 8이에요.","㉯는 둘레 (4 + 3) × 2 = 14, 넓이 4 × 3 = 12예요.","둘레가 긴 ㉮가 오히려 좁아요 — 둘레와 넓이는 다른 양이에요."],"asset":{"type":"geo","items":[{"w":150,"h":75,"grid":15,"poly":[[[15,15],[135,15],[135,30],[15,30]]],"show":[]},{"w":150,"h":75,"grid":15,"poly":[[[15,15],[75,15],[75,60],[15,60]]],"show":[]}]}},{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 두 직사각형 ㉮, ㉯에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"㉮는 둘레가 더 길지만 넓이는 더 좁다","correct":true},{"t":"㉮가 둘레도 넓이도 더 크다","mis":"M5-1-u6-X02"},{"t":"㉯가 둘레도 넓이도 더 크다","mis":"M5-1-u6-X02"},{"t":"두 도형은 넓이가 같다","mis":"M5-1-u6-X16"}],"explanation":["㉮는 둘레 (7 + 1) × 2 = 16, 넓이 7 × 1 = 7이에요.","㉯는 둘레 (4 + 3) × 2 = 14, 넓이 4 × 3 = 12예요.","둘레가 긴 ㉮가 오히려 좁아요 — 둘레와 넓이는 다른 양이에요."],"asset":{"type":"geo","items":[{"w":135,"h":75,"grid":15,"poly":[[[