('g5_1_math_u6_L06_challenge#7','math',5,1,'u6','L06','g5_1_math_u6_L06_challenge','lesson_challenge','M5-1-u6-C6',3,'sa','auto','넓이가 6 km²인 직사각형 모양 땅의 가로가 2000 m예요. 세로는 몇 km인가요?','{}'::text[],true,'{"seq":7,"concept":"M5-1-u6-C6","difficulty":3,"kind":"sa","stem":"넓이가 6 km²인 직사각형 모양 땅의 가로가 2000 m예요. 세로는 몇 km인가요?","answer":["3"],"explanation":["가로 2000 m = 2 km예요.","2 × □ = 6이니 □ = 6 ÷ 2예요.","6 ÷ 2 = 3 — 세로는 3 km예요."],"mis":"M5-1-u6-X14","variant_rule":{"alt":[{"stem":"넓이가 12 km²인 직사각형 모양 땅의 가로가 3000 m예요. 세로는 몇 km인가요?","answer":["4"],"explanation":["가로 3000 m = 3 km예요.","3 × □ = 12니 □ = 12 ÷ 3이에요.","12 ÷ 3 = 4 — 세로는 4 km예요."]},{"stem":"넓이가 20 km²인 직사각형 모양 땅의 가로가 4000 m예요. 세로는 몇 km인가요?","answer":["5"],"explanation":["가로 4000 m = 4 km예요.","4 × □ = 20이니 □ = 20 ÷ 4예요.","20 ÷ 4 = 5 — 세로는 5 km예요."]}]}}'::jsonb),
('g5_1_math_u6_L06_challenge#8','math',5,1,'u6','L06','g5_1_math_u6_L06_challenge','lesson_challenge','M5-1-u6-C6',4,'sa','auto','가로 1 m, 세로 2 m인 바닥에 한 변이 25 cm인 정사각형 타일을 빈틈없이 깔려고 해요. 타일은 몇 장 필요한가요?','{}'::text[],true,'{"seq":8,"concept":"M5-1-u6-C6","difficulty":4,"kind":"sa","stem":"가로 1 m, 세로 2 m인 바닥에 한 변이 25 cm인 정사각형 타일을 빈틈없이 깔려고 해요. 타일은 몇 장 필요한가요?","answer":["32"],"explanation":["1 m = 100 cm니 1 m² 칸 한 줄에 타일이 100 ÷ 25 = 4장, 4줄 — 1 m²에 4 × 4 = 16장이에요.","바닥의 넓이는 1 × 2 = 2예요 — 2 m²예요.","2 × 16 = 32 — 타일은 32장이에요."],"mis":"M5-1-u6-X07","variant_rule":{"alt":[{"stem":"가로 2 m, 세로 2 m인 바닥에 한 변이 50 cm인 정사각형 타일을 빈틈없이 깔려고 해요. 타일은 몇 장 필요한가요?","answer":["16"],"explanation":["1 m = 100 cm니 1 m² 칸 한 줄에 타일이 100 ÷ 50 = 2장, 2줄 — 1 m²에 2 × 2 = 4장이에요.","바닥의 넓이는 2 × 2 = 4예요 — 4 m²예요.","4 × 4 = 16 — 타일은 16장이에요."]},{"stem":"가로 3 m, 세로 2 m인 바닥에 한 변이 50 cm인 정사각형 타일을 빈틈없이 깔려고 해요. 타일은 몇 장 필요한가요?","answer":["24"],"explanation":["1 m = 100 cm니 1 m² 칸 한 줄에 타일이 100 ÷ 50 = 2장, 2줄 — 1 m²에 2 × 2 = 4장이에요.","바닥의 넓이는 3 × 2 = 6이에요 — 6 m²예요.","6 × 4 = 24 — 타일은 24장이에요."]}]}}'::jsonb),
('g5_1_math_u6_L06_challenge#9','math',5,1,'u6','L06','g5_1_math_u6_L06_challenge','lesson_challenge','M5-1-u6-C6',4,'mc','auto','1 km = 1000 m인데 1 km²가 1000 m²가 아니라 1000000 m²인 까닭은 무엇인가요?',ARRAY['M5-1-u6-X07','M5-1-u6-X01']::text[],true,'{"seq":9,"concept":"M5-1-u6-C6","difficulty":4,"kind":"mc","stem":"1 km = 1000 m인데 1 km²가 1000 m²가 아니라 1000000 m²인 까닭은 무엇인가요?","options":[{"t":"가로와 세로가 모두 1000배가 되므로","correct":true},{"t":"1 km²는 원래 1000000으로 약속했으므로","mis":"M5-1-u6-X07"},{"t":"넓이 단위는 길이 단위의 10배씩 커지므로","mis":"M5-1-u6-X07"},{"t":"km²는 둘레를 나타내므로","mis":"M5-1-u6-X01"}],"explanation":["한 변 1 km 정사각형은 가로 1000 m, 세로 1000 m예요.","1 m² 칸이 한 줄에 1000개씩 1000줄이에요.","1000 × 1000 = 1000000 — 두 방향 모두 1000배라서예요."],"variant_rule":{"alt":[{"stem":"1 m = 100 cm인데 1 m²가 100 cm²가 아니라 10000 cm²인 까닭은 무엇인가요?","options":[{"t":"가로와 세로가 모두 100배가 되므로","correct":true},{"t":"m²는 cm²보다 100배 넓기로 약속했으므로","mis":"M5-1-u6-X07"},{"t":"넓이는 둘레의 100배이므로","mis":"M5-1-u6-X01"},{"t":"cm²가 1 m를 100번 잰 것이므로","mis":"M5-1-u6-X06"}],"explanation":["한 변 1 m 정사각형은 가로 100 cm, 세로 100 cm예요.","1 cm² 칸이 한 줄에 100개씩 100줄이에요.","100 × 100 = 10000 — 두 방향 모두 100배라서예요."]}]}}'::jsonb),
('g5_1_math_u6_L06_challenge#10','math',5,1,'u6','L06','g5_1_math_u6_L06_challenge','lesson_challenge','M5-1-u6-C6',4,'essay','teacher','1 m = 100 cm인데 1 m²는 왜 100 cm²가 아니라 10000 cm²인지 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u6-C6","difficulty":4,"kind":"essay","stem":"1 m = 100 cm인데 1 m²는 왜 100 cm²가 아니라 10000 cm²인지 설명하세요.","answer_guide":{"answer":"예: 1 m²는 한 변이 1 m인 정사각형의 넓이이다. 1 m = 100 cm이므로 이 정사각형을 1 cm² 칸으로 덮으면 한 줄에 100칸씩 100줄이 된다. 100 × 100 = 10000이므로 1 m² = 10000 cm²이다. 길이는 한 방향만 100배지만 넓이는 가로와 세로 두 방향이 모두 100배가 되기 때문이다.","scoring_points":["1 m²가 한 변 1 m 정사각형의 넓이라고 썼는가","한 줄 100칸씩 100줄(100 × 100)으로 설명했는가","두 방향이 모두 100배라 10000배라고 썼는가"]},"explanation":["한 변 1 m = 100 cm예요.","1 cm² 칸이 100칸씩 100줄이에요.","100 × 100 = 10000 — 1 m² = 10000 cm²예요."]}'::jsonb),
('g5_1_math_u6_L07_basic#1','math',5,1,'u6','L07','g5_1_math_u6_L07_basic','lesson_basic','M5-1-u6-C7',1,'mc','auto','평행사변형에서 높이란 무엇인가요?',ARRAY['M5-1-u6-X11']::text[],true,'{"seq":1,"concept":"M5-1-u6-C7","difficulty":1,"kind":"mc","stem":"평행사변형에서 높이란 무엇인가요?","options":[{"t":"두 밑변 사이의 거리","correct":true},{"t":"가장 긴 변의 길이","mis":"M5-1-u6-X11"},{"t":"이웃한 변의 길이","mis":"M5-1-u6-X11"},{"t":"대각선의 길이","mis":"M5-1-u6-X11"}],"explanation":["평행한 두 변을 밑변이라고 해요.","두 밑변 사이의 거리가 높이예요.","높이는 밑변과 수직인 선분이라 이웃한 변과 달라요."],"variant_rule":{"alt":[{"stem":"평행사변형에서 밑변이란 무엇인가요?","options":[{"t":"평행한 두 변","correct":true},{"t":"가장 긴 변","mis":"M5-1-u6-X11"},{"t":"이웃한 두 변","mis":"M5-1-u6-X11"},{"t":"높이와 수직인 대각선","mis":"M5-1-u6-X11"}],"explanation":["평행사변형은 마주 보는 두 쌍의 변이 평행해요.","평행한 두 변을 밑변이라고 해요.","두 밑변 사이의 거리가 높이예요."]}]}}'::jsonb),
('g5_1_math_u6_L07_basic#2','math',5,1,'u6','L07','g5_1_math_u6_L07_basic','lesson_basic','M5-1-u6-C7',1,'sa','auto','밑변이 5 cm, 높이가 3 cm인 평행사변형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":2,"concept":"M5-1-u6-C7","difficulty":1,"kind":"sa","stem":"밑변이 5 cm, 높이가 3 cm인 평행사변형의 넓이는 몇 cm²인가요?","answer":["15"],"explanation":["평행사변형의 넓이는 (밑변의 길이) × (높이)예요.","밑변 5, 높이 3을 곱해요.","5 × 3 = 15 — 넓이는 15 cm²예요."],"variant_rule":{"alt":[{"stem":"밑변이 9 cm, 높이가 4 cm인 평행사변형의 넓이는 몇 cm²인가요?","answer":["36"],"explanation":["평행사변형의 넓이는 (밑변의 길이) × (높이)예요.","밑변 9, 높이 4를 곱해요.","9 × 4 = 36 — 넓이는 36 cm²예요."]},{"stem":"밑변이 6 m, 높이가 7 m인 평행사변형의 넓이는 몇 m²인가요?","answer":["42"],"explanation":["평행사변형의 넓이는 (밑변의 길이) × (높이)예요.","밑변 6, 높이 7을 곱해요.","6 × 7 = 42 — 넓이는 42 m²예요."]}]}}'::jsonb),
('g5_1_math_u6_L07_basic#3','math',5,1,'u6','L07','g5_1_math_u6_L07_basic','lesson_basic','M5-1-u6-C7',1,'mc','auto','평행사변형의 넓이를 구하는 식은 어느 것인가요?',ARRAY['M5-1-u6-X09','M5-1-u6-X01','M5-1-u6-X10']::text[],true,'{"seq":3,"concept":"M5-1-u6-C7","difficulty":1,"kind":"mc","stem":"평행사변형의 넓이를 구하는 식은 어느 것인가요?","options":[{"t":"(밑변의 길이) × (높이)","correct":true},{"t":"(밑변) × (이웃한 변)","mis":"M5-1-u6-X09"},{"t":"(밑변 + 높이) × 2","mis":"M5-1-u6-X01"},{"t":"(밑변의 길이) × (높이) ÷ 2","mis":"M5-1-u6-X10"}],"explanation":["한쪽 삼각형을 잘라 반대쪽에 붙이면 직사각형이 돼요.","그 직사각형의 가로는 밑변, 세로는 높이예요.","그래서 (밑변의 길이) × (높이)예요."],"variant_rule":{"alt":[{"stem":"평행사변형의 넓이를 구할 때 꼭 알아야 하는 두 길이는 무엇인가요?","options":[{"t":"밑변의 길이와 높이","correct":true},{"t":"밑변의 길이와 이웃한 변의 길이","mis":"M5-1-u6-X09"},{"t":"두 대각선의 길이","mis":"M5-1-u6-X13"},{"t":"네 변의 길이","mis":"M5-1-u6-X01"}],"explanation":["평행사변형의 넓이는 (밑변의 길이) × (높이)예요.","이웃한 변은 비스듬해서 넓이에 쓰지 않아요.","그래서 밑변의 길이와 높이를 알아야 해요."]}]}}'::jsonb),
('g5_1_math_u6_L07_basic#4','math',5,1,'u6','L07','g5_1_math_u6_L07_basic','lesson_basic','M5-1-u6-C7',1,'sa','auto','밑변이 10 cm, 높이가 8 cm인 평행사변형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":4,"concept":"M5-1-u6-C7","difficulty":1,"kind":"sa","stem":"밑변이 10 cm, 높이가 8 cm인 평행사변형의 넓이는 몇 cm²인가요?","answer":["80"],"explanation":["평행사변형의 넓이는 (밑변의 길이) × (높이)예요.","밑변 10, 높이 8을 곱해요.","10 × 8 = 80 — 넓이는 80 cm²예요."],"variant_rule":{"alt":[{"stem":"밑변이 11 cm, 높이가 9 cm인 평행사변형의 넓이는 몇 cm²인가요?","answer":["99"],"explanation":["평행사변형의 넓이는 (밑변의 길이) × (높이)예요.","밑변 11, 높이 9를 곱해요.","11 × 9 = 99 — 넓이는 99 cm²예요."]},{"stem":"밑변이 12 m, 높이가 6 m인 평행사변형의 넓이는 몇 m²인가요?","answer":["72"],"explanation":["평행사변형의 넓이는 (밑변의 길이) × (높이)예요.","밑변 12, 높이 6을 곱해요.","12 × 6 = 72 — 넓이는 72 m²예요."]}]}}'::jsonb),
('g5_1_math_u6_L07_basic#5','math',5,1,'u6','L07','g5_1_math_u6_L07_basic','lesson_basic','M5-1-u6-C7',2,'mc','auto','평행사변형 ㄱㄴㄷㄹ에서 변 ㄴㄷ을 밑변으로 할 때 높이를 나타내는 선분은 어느 것인가요?',ARRAY['M5-1-u6-X11','M5-1-u6-X17']::text[],true,'{"seq":5,"concept":"M5-1-u6-C7","difficulty":2,"kind":"mc","stem":"평행사변형 ㄱㄴㄷㄹ에서 변 ㄴㄷ을 밑변으로 할 때 높이를 나타내는 선분은 어느 것인가요?","options":[{"t":"선분 ㄱㅁ","correct":true},{"t":"선분 ㄱㄴ","mis":"M5-1-u6-X11"},{"t":"선분 ㄴㄷ","mis":"M5-1-u6-X17"},{"t":"선분 ㄹㄷ","mis":"M5-1-u6-X11"}],"explanation":["높이는 두 밑변(변 ㄱㄹ과 변 ㄴㄷ) 사이의 거리예요.","밑변과 수직으로 만나는 선분을 찾아요 — 직각 표시가 있어요.","그래서 높이는 선분 ㄱㅁ이에요. 이웃한 변은 비스듬해 높이가 아니에요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"pts":{"ㄱ":[45,15],"ㄴ":[15,75],"ㄷ":[105,75],"ㄹ":[135,15],"ㅁ":[45,75]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㅁ"]],"right":[["ㄱ","ㅁ","ㄷ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 평행사변형 ㄱㄴㄷㄹ에서 변 ㄴㄷ을 밑변으로 할 때 높이를 나타내는 선분은 어느 것인가요?","options":[{"t":"선분 ㄹㅁ","correct":true},{"t":"선분 ㄹㄷ","mis":"M5-1-u6-X11"},{"t":"선분 ㄴㄷ","mis":"M5-1-u6-X17"},{"t":"선분 ㄱㄴ","mis":"M5-1-u6-X11"}],"explanation":["높이는 두 밑변(변 ㄱㄹ과 변 ㄴㄷ) 사이의 거리예요.","밑변과 수직으로 만나는 선분을 찾아요 — 직각 표시가 있어요.","그래서 높이는 선분 ㄹㅁ이에요. 이웃한 변은 비스듬해 높이가 아니에요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"pts":{"ㄱ":[15,15],"ㄴ":[45,75],"ㄷ":[135,75],"ㄹ":[105,15],"ㅁ":[105,75]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄹ","ㅁ"]],"right":[["ㄹ","ㅁ","ㄴ"]]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 평행사변형 ㄱㄴㄷㄹ에서 변 ㄴㄷ을 밑변으로 할 때 높이를 나타내는 선분은 어느 것인가요?","options":[{"t":"선분 ㅁㅂ","correct":true},{"t":"선분 ㄱㄴ","mis":"M5-1-u6-X11"},{"t":"선분 ㄴㄷ","mis":"M5-1-u6-X17"},{"t":"선분 ㄹㄷ","mis":"M5-1-u6-X11"}],"explanation":["높이는 두 밑변(변 ㄱㄹ과 변 ㄴㄷ) 사이의 거리예요.","밑변과 수직으로 만나는 선분을 찾아요 — 직각 표시가 있어요.","그래서 높이는 선분 ㅁㅂ이에요. 이웃한 변은 비스듬해 높이가 아니에요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"pts":{"ㄱ":[30,15],"ㄴ":[15,75],"ㄷ":[105,75],"ㄹ":[120,15],"ㅂ":[75,15],"ㅁ":[75,75]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㅁ","ㅂ"]],"right":[["ㅂ","ㅁ","ㄷ"]]}],"tag":false}}]}}'::jsonb),
